window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[102]={"id":"102","numero":102,"titre":"Diplopie","objectifs":[{"id":"102-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la systématisation des nerfs crâniens III, IV, VI et du faisceau longitudinal médial","contenu":"<p>Trois <span class=\"kw-def\">nerfs oculomoteurs</span> innervent <span class=\"kw-clinique\">les</span> six muscles oculomoteurs de chaque œil. Leur trajet — du noyau dans le tronc cérébral jusqu'à l'orbite en passant par le <span class=\"kw-def\">sinus caverneux</span> — explique la sémiologie observée et les pièges étiologiques (<span class=\"kw-alerte\">HTIC</span>, fracture du rocher, anévrisme communicante postérieure).</p>\n\n      <h4>1 · Champs d'action des 6 muscles oculomoteurs</h4>\n      <table >\n        <thead>\n          <tr>\n            <th>Muscle</th>\n            <th>Innervation</th>\n            <th>Champ d'action</th>\n            <th>Diplopie si paralysie</th>\n            <th>Position vicieuse compensatrice de la tête</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Droit médial (DM)</strong></td><td><strong>III</strong></td><td>Dedans</td><td><span class=\"kw-clinique\">Horizontale croisée</span></td><td>Face tournée côté sain</td></tr>\n          <tr><td><strong>Droit supérieur (DS)</strong></td><td><strong>III</strong></td><td>Haut et dehors</td><td><span class=\"kw-clinique\">Verticale</span></td><td>Menton élevé</td></tr>\n          <tr><td><strong>Droit inférieur (DI)</strong></td><td><strong>III</strong></td><td>Bas et dehors</td><td><span class=\"kw-clinique\">Verticale</span></td><td>Menton abaissé côté sain</td></tr>\n          <tr><td><strong>Oblique inférieur (OI)</strong></td><td><strong>III</strong></td><td>Haut et dedans</td><td><span class=\"kw-clinique\">Verticale</span></td><td>Tête en arrière, face tournée du côté sain, menton abaissé</td></tr>\n          <tr><td><strong>Oblique supérieur (OS)</strong></td><td><strong>IV</strong></td><td>Bas et dedans</td><td><span class=\"kw-clinique\">Verticale</span></td><td>Face inclinée côté sain (<span class=\"kw-def\">signe de Bielschowski</span>)</td></tr>\n          <tr><td><strong>Droit latéral (DL)</strong></td><td><strong>VI</strong></td><td>Dehors</td><td><span class=\"kw-clinique\">Horizontale homonyme</span></td><td>Tête tournée du côté atteint</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Mémo anatomie / champ d'action.</strong> Pour <span class=\"kw-clinique\">les</span> <strong>muscles droits</strong>, anatomie et champ d'action sont <em>superposables</em> (le muscle tire le globe vers lui, le regard se dir<span class=\"kw-chiffre\">ige</span> vers le muscle). Pour les <strong>muscles obliques</strong>, anatomie et champ d'action sont <em>opposés</em> (système de poulie → le globe est tiré dans la direction opposée à l'insertion).\n      </div>\n\n      <h4>2 · Nerf oculomoteur (III) — la plus riche des paires oculomotrices</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Noyau</strong></td><td>Mésencéphale, à la hauteur des <span class=\"kw-def\">colliculus supérieurs</span>.</td></tr>\n          <tr><td><strong>Trajet</strong></td><td>1. Émerge à la face antérieure du tronc cérébral (fosse interpédonculaire). <br>2. Chemine entre <span class=\"kw-def\">a. cérébrale postérieure</span> et <span class=\"kw-def\">a. cérébelleuse supérieure</span>. <br>3. Passe à proximité de l'<span class=\"kw-def\">a. communicante postérieure</span> (siège classique d'anévrisme). <br>4. Traverse le <span class=\"kw-def\">sinus caverneux</span> puis pénètre l'orbite.</td></tr>\n          <tr><td><strong>Couche extrinsèque (profonde)</strong></td><td><strong>Innervation :</strong> releveur de la paupière supérieure ; droit médial ; droit supérieur ; droit inférieur ; oblique inférieur. <br><strong>Sémio si atteinte :</strong> <span class=\"kw-clinique\">ptosis</span> (peut <span class=\"kw-alerte\">masquer la diplopie</span> — « ptosis providentiel ») ; <span class=\"kw-clinique\">strabisme externe</span> (œil en abduction) ; <span class=\"kw-clinique\">diplopie horizontale croisée</span> (DM) ou verticale (DS / DI / OI) ; paralysie de l'adduction, de l'élévation, de l'abaissement.</td></tr>\n          <tr><td><strong>Couche intrinsèque (superficielle)</strong></td><td><strong>Innervation :</strong> parasympathique → muscles ciliaires (accommodation du cristallin) + sphincter irien (réflexe photomoteur). <br><strong>Sémio si atteinte :</strong> perte de l'accommodation ; <span class=\"kw-clinique\">mydriase aréactive</span> unilatérale (ou anisocorie à un moindre degré).</td></tr>\n          <tr><td><strong>Paralysie partielle ou totale</strong></td><td>Atteinte de quelques muscles seulement, de la couche extrinsèque seule, ou intrinsèque seule.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Piège à connaître.</strong> Une <span class=\"kw-alerte\">mydriase isolée</span> n'est <strong>pas</strong> une paralysie du III. Elle correspond le plus souvent à une <span class=\"kw-def\">pupille d'Adie</span> ou à une mydriase pharmacologique.\n      </div>\n\n      <h4>3 · Nerf trochléaire (IV) — le plus fin, le plus exposé aux traumatismes crâniens</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Noyau</strong></td><td>Partie postérieure du mésencéphale (hauteur des colliculus inférieurs).</td></tr>\n          <tr><td><strong>Trajet</strong></td><td>1. Croise la ligne médiane (seul nerf crânien à émerger en arrière), contourne le tronc cérébral, pénètre l'orbite <strong>controlatérale</strong>. <br>2. Passe par le sinus caverneux avant l'orbite.</td></tr>\n          <tr><td><strong>Innervation</strong></td><td>Muscle <strong>oblique supérieur</strong> uniquement (regard <em>en bas et en dedans</em>). <br><em>Mémo : ancien nom « nerf pathétique » — on regarde en bas et en dedans quand on a honte.</em></td></tr>\n          <tr><td><strong>Atteinte du tronc ou du noyau</strong></td><td><span class=\"kw-clinique\">Diplopie verticale</span> accentuée lors du regard en bas et en dedans (<strong>gêne à la descente d'escaliers et à la lecture</strong>) ; paralysie d'abaissement en dedans ; <span class=\"kw-def\">signe de Bielschowski</span> (tête penchée et tournée vers le côté sain, menton abaissé — « torticolis oculaire »).</td></tr>\n          <tr><td><strong>Particularité</strong></td><td>Le IV est <span class=\"kw-alerte\">particulièrement vulnérable aux traumatismes crâniens</span> (même bénins).</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Nerf abducens (VI) — chef d'orchestre de la latéralité</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Noyau</strong></td><td>Pont, à hauteur du plancher du 4<sup>e</sup> ventricule.</td></tr>\n          <tr><td><strong>Trajet</strong></td><td>1. Chemine le long de la pointe du rocher (<span class=\"kw-alerte\">vulnérable à la fracture du rocher</span>). <br>2. Perfore la dure-mère et y est fixé (<span class=\"kw-alerte\">vulnérable à la traction du tronc cérébral lors de l'HTIC</span>). <br>3. Passe par le sinus caverneux avant l'orbite.</td></tr>\n          <tr><td><strong>Innervation</strong></td><td>Le noyau abducens est le <span class=\"kw-def\">centre de la latéralité</span> : <br><strong>Abduction de l'œil ipsilatéral :</strong> innervation directe du droit latéral. <br><strong>Adduction de l'œil controlatéral :</strong> via <span class=\"kw-clinique\">les</span> interneurones qui décussent dans le <span class=\"kw-def\">faisceau longitudinal médian (FLM)</span> et rejoignent le noyau du III controlatéral.</td></tr>\n          <tr><td><strong>Sémio si atteinte</strong></td><td><span class=\"kw-clinique\">Strabisme interne</span> (œil en adduction) ; <span class=\"kw-clinique\">diplopie horizontale homonyme</span> maximale ou accrue dans le regard en dehors ; paralysie de l'abduction ; position vicieuse de la tête du côté atteint.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>5 · Voies supranucléaires — « paralysies de fonction »</h4>\n      <p><span class=\"kw-clinique\">Les</span> voies supranucléaires relient les centres corticaux aux noyaux oculomoteurs : <strong>centre de la latéralité</strong> (mouvements horizontaux conjugués), <strong>centre de la verticalité</strong> (mouvements verticaux conjugués), <strong>centre de la convergence</strong> (vision de près).</p>\n\n      <p>Leur atteinte donne des <span class=\"kw-def\">paralysies de fonction</span> caractérisées par une <strong>paralysie oculomotrice sans diplopie</strong> (<span class=\"kw-clinique\">les</span> 2 yeux restent parallèles) :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Syndrome de Foville</span></strong> — paralysie de la <span class=\"kw-def\">latéralité</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Syndrome de Parinaud</span></strong> — paralysie de la <span class=\"kw-def\">verticalité</span> associée à une paralysie de la convergence. <span class=\"kw-etio\">Très évocateur d'un pinéalome (tumeur épiphysaire) +++.</span></li>\n      </ul>\n\n      <h4>6 · Voies internucléaires — Ophtalmoplégie internucléaire (OIN, atteinte du FLM)</h4>\n      <p>Le <span class=\"kw-def\">faisceau longitudinal médian (FLM)</span> = « bandelette longitudinale postérieure » relie <span class=\"kw-clinique\">les</span> noyaux oculomoteurs entre eux. Son atteinte donne l'<span class=\"kw-def\">ophtalmoplégie internucléaire</span>, à connaître absolument.</p>\n\n      <table >\n        <thead>\n          <tr><th></th><th>OIN gauche</th><th>OIN droite</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Révélation</strong></td><td>Lors du regard à <strong>droite</strong></td><td>Lors du regard à <strong>gauche</strong></td></tr>\n          <tr><td><strong>Œil gauche</strong></td><td><span class=\"kw-clinique\">Paralysie de l'adduction</span> (ne peut pas regarder à droite)</td><td><span class=\"kw-clinique\">Nystagmus</span> lors du regard à gauche</td></tr>\n          <tr><td><strong>Œil droit</strong></td><td><span class=\"kw-clinique\">Nystagmus</span> lors du regard à droite</td><td><span class=\"kw-clinique\">Paralysie de l'adduction</span> (ne peut pas regarder à gauche)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Règle générale OIN.</strong> Il existe toujours un <span class=\"kw-clinique\">déficit d'adduction homolatéral</span> à la <span class=\"kw-clinique\">lésion</span> + un <span class=\"kw-clinique\">nystagmus de l'œil abducteur</span> controlatéral. <br><strong>Distinction avec atteinte du III :</strong> faire <em>loucher</em> le patient — l'adduction en convergence est <strong>préservée</strong> dans l'OIN (atteinte du FLM seul), pas dans une atteinte du III.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau étiologique OIN.</strong> <span class=\"kw-alerte\">Avant 40 ans → évoquer SEP +++</span>. <span class=\"kw-alerte\">Après 50 ans (surtout si FRCV) → évoquer un infarctus cérébral (lacune) du tronc cérébral.</span>\n      </div>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 430\" role=\"img\" aria-label=\"Schéma de systématisation des trois nerfs oculomoteurs et du faisceau longitudinal médian. Le nerf III naît du mésencéphale, émerge à la fosse interpédonculaire, chemine entre l'artère cérébrale postérieure et l'artère cérébelleuse supérieure puis près de l'artère communicante postérieure (siège classique d'anévrisme), traverse le sinus caverneux et gagne l'orbite. Le nerf IV naît du mésencéphale postérieur, est le seul nerf à croiser la ligne médiane et à émerger en arrière, contourne le tronc cérébral, passe par le sinus caverneux et gagne l'orbite controlatérale ; il est très vulnérable aux traumatismes crâniens. Le nerf VI naît du pont, chemine le long de la pointe du rocher où il est vulnérable à la fracture, est fixé à la dure-mère ce qui le rend vulnérable à la traction lors d'une hypertension intracrânienne, passe par le sinus caverneux et gagne l'orbite. En bas, le circuit du faisceau longitudinal médian explique l'ophtalmoplégie internucléaire : le noyau du VI commande l'abduction de l'œil ipsilatéral et envoie des interneurones qui décussent dans le faisceau longitudinal médian vers le noyau du III controlatéral pour l'adduction synchrone ; une atteinte du faisceau donne un déficit d'adduction homolatéral à la lésion et un nystagmus de l'œil abducteur controlatéral, avec convergence préservée.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Trajets des nerfs III / IV / VI — du noyau à l'orbite</text>\n\n          <!-- Colonne III (purple) -->\n          <rect class=\"fb-purple\" x=\"14\" y=\"32\" width=\"168\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"98\" y=\"51\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">III — oculomoteur</text>\n          <line class=\"ln\" x1=\"98\" y1=\"62\" x2=\"98\" y2=\"74\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"98,80 93,72 103,72\"/>\n          <rect class=\"fb-purple\" x=\"14\" y=\"82\" width=\"168\" height=\"28\" rx=\"5\"/>\n          <text class=\"tx-purple\" x=\"98\" y=\"100\" text-anchor=\"middle\" font-size=\"10.5\">Noyau mésencéphale</text>\n          <line class=\"ln\" x1=\"98\" y1=\"110\" x2=\"98\" y2=\"120\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"98,126 93,118 103,118\"/>\n          <rect class=\"fb-purple\" x=\"14\" y=\"128\" width=\"168\" height=\"28\" rx=\"5\"/>\n          <text class=\"tx-purple\" x=\"98\" y=\"146\" text-anchor=\"middle\" font-size=\"10.5\">Fosse interpédonculaire</text>\n          <line class=\"ln\" x1=\"98\" y1=\"156\" x2=\"98\" y2=\"166\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"98,172 93,164 103,164\"/>\n          <rect class=\"fb-red\" x=\"14\" y=\"174\" width=\"168\" height=\"40\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"98\" y=\"190\" text-anchor=\"middle\" font-size=\"9.5\">Près a. communicante post.</text>\n          <text class=\"tx-red\" x=\"98\" y=\"204\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">(anévrisme +++)</text>\n\n          <!-- Colonne IV (teal) -->\n          <rect class=\"fb-teal\" x=\"196\" y=\"32\" width=\"168\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"280\" y=\"51\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">IV — trochléaire</text>\n          <line class=\"ln\" x1=\"280\" y1=\"62\" x2=\"280\" y2=\"74\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"280,80 275,72 285,72\"/>\n          <rect class=\"fb-teal\" x=\"196\" y=\"82\" width=\"168\" height=\"28\" rx=\"5\"/>\n          <text class=\"tx-teal\" x=\"280\" y=\"100\" text-anchor=\"middle\" font-size=\"10.5\">Noyau mésencéphale post.</text>\n          <line class=\"ln\" x1=\"280\" y1=\"110\" x2=\"280\" y2=\"120\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"280,126 275,118 285,118\"/>\n          <rect class=\"fb-teal\" x=\"196\" y=\"128\" width=\"168\" height=\"28\" rx=\"5\"/>\n          <text class=\"tx-teal\" x=\"280\" y=\"146\" text-anchor=\"middle\" font-size=\"10\">Croise la ligne médiane</text>\n          <line class=\"ln\" x1=\"280\" y1=\"156\" x2=\"280\" y2=\"166\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"280,172 275,164 285,164\"/>\n          <rect class=\"fb-red\" x=\"196\" y=\"174\" width=\"168\" height=\"40\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"190\" text-anchor=\"middle\" font-size=\"9\">Émerge en arrière, le plus fin</text>\n          <text class=\"tx-red\" x=\"280\" y=\"204\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">(trauma crânien +++)</text>\n\n          <!-- Colonne VI (amber) -->\n          <rect class=\"fb-amber\" x=\"378\" y=\"32\" width=\"168\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"462\" y=\"51\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">VI — abducens</text>\n          <line class=\"ln\" x1=\"462\" y1=\"62\" x2=\"462\" y2=\"74\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"462,80 457,72 467,72\"/>\n          <rect class=\"fb-amber\" x=\"378\" y=\"82\" width=\"168\" height=\"28\" rx=\"5\"/>\n          <text class=\"tx-amber\" x=\"462\" y=\"100\" text-anchor=\"middle\" font-size=\"10.5\">Noyau pont (4ᵉ ventricule)</text>\n          <line class=\"ln\" x1=\"462\" y1=\"110\" x2=\"462\" y2=\"120\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"462,126 457,118 467,118\"/>\n          <rect class=\"fb-red\" x=\"378\" y=\"128\" width=\"168\" height=\"28\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"462\" y=\"146\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\">Pointe du rocher (fracture)</text>\n          <line class=\"ln\" x1=\"462\" y1=\"156\" x2=\"462\" y2=\"166\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"462,172 457,164 467,164\"/>\n          <rect class=\"fb-red\" x=\"378\" y=\"174\" width=\"168\" height=\"40\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"462\" y=\"190\" text-anchor=\"middle\" font-size=\"9.5\">Fixé à la dure-mère</text>\n          <text class=\"tx-red\" x=\"462\" y=\"204\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">(traction <span class=\"kw-alerte\">HTIC</span> +++)</text>\n\n          <!-- Convergence vers sinus caverneux puis orbite -->\n          <line class=\"ln\" x1=\"98\" y1=\"214\" x2=\"98\" y2=\"226\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"214\" x2=\"280\" y2=\"226\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"462\" y1=\"214\" x2=\"462\" y2=\"226\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"98\" y1=\"226\" x2=\"462\" y2=\"226\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"226\" x2=\"280\" y2=\"238\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"280,244 275,236 285,236\"/>\n          <rect class=\"fb-grey\" x=\"150\" y=\"246\" width=\"260\" height=\"28\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"264\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Sinus caverneux → orbite</text>\n\n          <!-- Bloc FLM / OIN -->\n          <text class=\"tx-title\" x=\"280\" y=\"298\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Circuit du FLM — ophtalmoplégie internucléaire (OIN)</text>\n          <rect class=\"fb-amber\" x=\"26\" y=\"312\" width=\"150\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"101\" y=\"332\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">Noyau VI</text>\n          <text class=\"tx-amber\" x=\"101\" y=\"348\" text-anchor=\"middle\" font-size=\"9.5\">→ abduction œil ipsi (DL)</text>\n          <line class=\"ln\" x1=\"176\" y1=\"336\" x2=\"220\" y2=\"336\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"226,336 218,331 218,341\"/>\n          <rect class=\"fb-red\" x=\"226\" y=\"312\" width=\"108\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"332\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">FLM (décusse)</text>\n          <text class=\"tx-red\" x=\"280\" y=\"348\" text-anchor=\"middle\" font-size=\"9\"><span class=\"kw-clinique\">lésion</span> = OIN</text>\n          <line class=\"ln\" x1=\"334\" y1=\"336\" x2=\"378\" y2=\"336\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"384,336 376,331 376,341\"/>\n          <rect class=\"fb-purple\" x=\"384\" y=\"312\" width=\"150\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"459\" y=\"332\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">Noyau III controlat.</text>\n          <text class=\"tx-purple\" x=\"459\" y=\"348\" text-anchor=\"middle\" font-size=\"9.5\">→ adduction (DM)</text>\n\n          <rect class=\"fb-red\" x=\"14\" y=\"372\" width=\"324\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"176\" y=\"390\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">OIN = déficit adduction homolatéral</text>\n          <text class=\"tx-red\" x=\"176\" y=\"406\" text-anchor=\"middle\" font-size=\"9.5\">+ nystagmus œil abducteur controlatéral</text>\n          <rect class=\"fb-ok\" x=\"350\" y=\"372\" width=\"196\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"448\" y=\"390\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">Convergence PRÉSERVÉE</text>\n          <text class=\"tx-ok\" x=\"448\" y=\"406\" text-anchor=\"middle\" font-size=\"9.5\">(distingue d'une atteinte du III)</text>\n        </svg>\n        <figcaption><span class=\"kw-clinique\">Les</span> trois nerfs convergent vers le <strong>sinus caverneux</strong> avant l'orbite (siège commun d'atteinte). En bas, le <strong>FLM</strong> relie le noyau du VI au noyau du III controlatéral : sa lésion donne l'<strong>OIN</strong> (déficit d'adduction homolatéral + nystagmus controlatéral, convergence préservée).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 104 — <span class=\"kw-ttt\">Sclérose</span> en plaques · 340 — <span class=\"kw-def\">Accident vasculaire cérébral</span></em></p>","frequence":3},{"id":"102-2","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir déterminer si une diplopie est mono- ou binoculaire","contenu":"<p>La <span class=\"kw-def\">diplopie</span> est la vision double d'un objet unique (une vision floue peut y correspondre). La première étape diagnostique est <strong>obl<span class=\"kw-chiffre\">iga</span>toirement</strong> de différencier <strong>mono</strong>- de <strong>binoculaire</strong> par un geste simple : <span class=\"kw-clinique\">occlusion d'un œil</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Diplopie <strong>monoculaire</strong></th><th>Diplopie <strong>binoculaire</strong></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"kw-clinique\">Persiste à l'occlusion de l'œil sain</span> <br>Disparaît à l'occlusion de l'œil atteint</td>\n            <td>Présente <span class=\"kw-clinique\">les</span> 2 yeux ouverts <br><span class=\"kw-clinique\">Disparaît à l'occlusion de n'importe quel œil</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Cause <span class=\"kw-etio\">ophtalmologique</span> (anomalie de l'œil atteint)</td>\n            <td>Trouble du <span class=\"kw-def\">parallélisme oculaire acquis</span> + installation aiguë ou subaiguë, d'origine neurologique ou orbitaire</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies</strong></td>\n            <td><strong>Cornée</strong> (diffraction des rayons) : ast<span class=\"kw-chiffre\">igm</span>atisme important, kératocône, taie cornéenne (séquelle de kératite ou traumatisme) <br><strong>Iris :</strong> iridodialyse traumatique <br><strong>Cristallin :</strong> cataracte nucléaire, implant décentré <br><strong>Macula (rare) :</strong> membrane épirétinienne tractionnelle</td>\n            <td><strong>Paralysie oculomotrice</strong> le plus souvent : <br>– Atteinte du SNC (noyaux : mésencéphale III/IV, pont VI) <br>– Atteinte du tronc des nerfs oculomoteurs <br>– Atteinte de la <span class=\"kw-def\">jonction neuromusculaire</span> (myasthénie) <br>– Atteinte des <strong>muscles oculomoteurs</strong> (Basedow, myosite)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Urgence</span></strong></td>\n            <td><span class=\"kw-alerte\">Pas d'urgence</span> — examen ophtalmologique programmé. Cause fonctionnelle évoquée si bilan normal.</td>\n            <td><span class=\"kw-alerte\">Requiert souvent une PEC urgente.</span> Un trouble <span class=\"kw-etio\">congénital</span> ou ancien d'installation lente ne se manifeste généralement <strong>pas</strong> par une diplopie ❌</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Piège.</strong> Une diplopie peut être <span class=\"kw-alerte\">méconnue</span> lorsqu'un <span class=\"kw-clinique\">ptosis</span> ou un <span class=\"kw-clinique\">œdème palpébral</span> occlut l'œil paralysé — ce qui supprime mécaniquement la vision double (« ptosis providentiel » de l'atteinte du III).\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-clinique\">disparition du symptôme à l'occlusion d'un œil</span> a la même valeur diagnostique qu'une diplopie binoculaire confirmée — c'est le geste simple qui oriente immédiatement la suite (binoculaire = neurologique/orbitaire urgent ; monoculaire = ophtalmo, programmable).\n      </div>","frequence":0},{"id":"102-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la définition des tests cliniques ophtalmologiques","contenu":"<p>Quatre tests cliniques + un test paraclinique fondent l'examen de la motilité oculaire devant une diplopie binoculaire : <strong>reflets cornéens</strong>, <strong>cover-test</strong>, <strong>examen au verre rouge</strong>, <strong>test de Hess-Lancaster</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Test</th><th>Principe</th><th>Résultat normal</th><th>Si paralysie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reflets cornéens</strong></td>\n            <td>Source lumineuse dirigée sur <span class=\"kw-clinique\">les</span> yeux ; on observe la position des reflets cornéens.</td>\n            <td><span class=\"kw-clinique\">Les</span> 2 reflets se projettent au <span class=\"kw-bio\">centre des deux pupilles</span>.</td>\n            <td><span class=\"kw-clinique\">L'un des 2 reflets n'est pas centré</span> (œil dévié).</td>\n          </tr>\n          <tr>\n            <td><strong>Cover-test (sous-écran)</strong></td>\n            <td>Sujet fixe un point droit devant lui au loin. On masque un œil avec un cache, puis on déplace le cache sur l'œil opposé.</td>\n            <td><span class=\"kw-bio\">Aucun mouvement</span> lorsqu'on lève le cache (parallélisme oculomoteur conservé).</td>\n            <td><span class=\"kw-clinique\">Mouvement de restitution</span> : l'œil non fixateur apparaît dévié puis se redresse pour prendre la fixation (strabisme paralytique).</td>\n          </tr>\n          <tr>\n            <td><strong>Examen au verre rouge</strong></td>\n            <td>Verre rouge placé devant un œil (par convention le droit) ; le sujet fixe un point lumineux blanc en face de lui.</td>\n            <td><span class=\"kw-bio\">Un seul point lumineux de couleur rose</span> (<span class=\"kw-clinique\">les</span> 2 images sont fusionnées) dans toutes les positions du regard.</td>\n            <td><span class=\"kw-clinique\">2 points séparés</span> — le patient voit 1 point rouge et 1 point blanc. L'analyse du décalage identifie le muscle déficitaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Test de Hess-Lancaster</strong></td>\n            <td>Verre de couleur différente devant chaque œil (rouge <span class=\"kw-bio\">vs</span> vert). Le patient déplace une flèche lumineuse rouge pour la superposer à une flèche verte déplacée par l'examinateur.</td>\n            <td>Relevé graphique <span class=\"kw-bio\">symétrique</span> de l'oculomotricité dans <span class=\"kw-clinique\">les</span> différentes positions du regard.</td>\n            <td><span class=\"kw-clinique\">Œil paralysé : cadre plus petit</span> que la normale (hypoaction). <br><span class=\"kw-clinique\">Œil controlatéral : cadre plus grand</span> que la normale (hyperaction des agonistes controlatéraux — loi de Hering).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus · Examen au verre rouge — analyse du décalage</h4>\n      <table >\n        <thead>\n          <tr><th>Décalage observé</th><th>Type de diplopie</th><th>Œil concerné</th><th>Exemple de paralysie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Point rouge vu <strong>à droite</strong> du point blanc</td>\n            <td><span class=\"kw-clinique\">Diplopie homonyme</span></td>\n            <td>Œil en <span class=\"kw-clinique\">convergence</span></td>\n            <td><strong>Paralysie du VI</strong></td>\n          </tr>\n          <tr>\n            <td>Point rouge vu <strong>à gauche</strong> du point blanc</td>\n            <td><span class=\"kw-clinique\">Diplopie croisée</span></td>\n            <td>Œil en <span class=\"kw-clinique\">divergence</span></td>\n            <td><strong>Paralysie du III</strong> (atteinte du DM)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Loi de Hering / Loi de Sherrington (rang C).</strong> Toute paralysie d'un muscle entraîne une <em>hyperaction</em> de son agoniste controlatéral (Hering : influx envoyé en quantité égale aux 2 agonistes) et un <em>relâchement</em> de son antagoniste homolatéral (Sherrington). C'est ce qui explique le cadre « plus grand que la normale » de l'œil sain au Lancaster.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'écart entre <span class=\"kw-clinique\">les</span> 2 images au verre rouge <span class=\"kw-clinique\">augmente dans le champ d'action du muscle paralysé</span> — c'est cette propriété qui permet de déterminer précisément les muscles atteints (cf cartes des champs d'action de l'obj-0).\n      </div>","frequence":0},{"id":"102-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la définition des ductions et des vergences","contenu":"<p>L'examen de la motilité oculaire repose sur trois types de mouvements aux définitions précises — utilisées dans la rédaction clinique de la paralysie oculomotrice.</p>\n\n      <table >\n        <thead>\n          <tr><th>Notion</th><th>Définition</th><th>Mouvements</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Ductions</strong></td>\n            <td>Mouvements <span class=\"kw-def\">monoculaires</span> — explorent la motilité oculaire dans <span class=\"kw-clinique\">les</span> différentes positions du regard de <strong>chaque œil séparément</strong>.</td>\n            <td><strong>Abduction :</strong> mouvement vers l'extérieur (en dehors). <br><strong>Adduction :</strong> mouvement vers l'intérieur (en dedans).</td>\n          </tr>\n          <tr>\n            <td><strong>Versions</strong></td>\n            <td>Mouvements oculaires <span class=\"kw-def\">bilatéraux conjugués des 2 yeux</span> — explorent la motilité oculaire dans la même direction.</td>\n            <td>Latéroversion droite, latéroversion gauche, sursumversion (haut), deorsumversion (bas).</td>\n          </tr>\n          <tr>\n            <td><strong>Vergences</strong></td>\n            <td>Mouvements oculaires de <span class=\"kw-def\">sens opposé des 2 yeux</span> — cas particulier des mouvements binoculaires.</td>\n            <td><strong>Convergence :</strong> mouvement des 2 yeux vers l'intérieur (vision de près, lecture). <br><strong>Divergence :</strong> mouvement des 2 yeux vers l'extérieur.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Utilité clinique.</strong> L'<span class=\"kw-def\">examen des ductions</span> permet d'isoler le muscle déficitaire (œil par œil), tandis que l'<span class=\"kw-def\">examen des versions</span> dépiste l'<span class=\"kw-clinique\">asymétrie</span> clinique entre <span class=\"kw-clinique\">les</span> 2 yeux (= visible « à l'œil nu » dans une consultation). La <strong>convergence préservée</strong> est l'argument-clé pour différencier une OIN d'une atteinte du III (cf <em>obj-0</em>).\n      </div>","frequence":0},{"id":"102-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la définition des tropies","contenu":"<p>La <span class=\"kw-def\">tropie</span> est la déviation des axes visuels, <strong>synonyme de strabisme</strong>. Le préfixe précise la direction de la déviation.</p>\n\n      <table >\n        <thead>\n          <tr><th>Tropie</th><th>Définition</th><th>Repère</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Ésotropie</strong></td><td>Déviation de l'œil vers l'<span class=\"kw-clinique\">intérieur</span> (en dedans)</td><td>Strabisme convergent</td></tr>\n          <tr><td><strong>Exotropie</strong></td><td>Déviation de l'œil vers l'<span class=\"kw-clinique\">extérieur</span> (en dehors)</td><td>Strabisme divergent</td></tr>\n          <tr><td><strong>Hypertropie</strong></td><td>Déviation de l'œil vers le <span class=\"kw-clinique\">haut</span></td><td>Strabisme vertical supérieur</td></tr>\n          <tr><td><strong>Hypotropie</strong></td><td>Déviation de l'œil vers le <span class=\"kw-clinique\">bas</span></td><td>Strabisme vertical inférieur</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Une <span class=\"kw-clinique\">ésotropie</span> évoque classiquement une <strong>paralysie du VI</strong> (œil dévié en adduction par hyperaction du DM controlatéral du fait du déficit d'abduction). Une <span class=\"kw-clinique\">exotropie</span> évoque une <strong>paralysie du III</strong> (déficit d'adduction → œil dévié en abduction par le DL).\n      </div>","frequence":0},{"id":"102-6","rang":"A","rubrique":"Contenu multimédia","titre":"Connaître la symptomatologie et la position vicieuse de la tête dans une paralysie complète du III, du IV, du VI","contenu":"<p>Trois sémiologies stéréotypées à savoir reconnaître <strong>à la photo</strong>. Chaque paralysie oculomotrice complète associe : une <span class=\"kw-clinique\">déviation du globe en position primaire</span>, une <span class=\"kw-clinique\">diplopie</span> dans une direction caractéristique, et une <span class=\"kw-clinique\">position vicieuse de la tête (PVT)</span> compensatrice prise spontanément par le patient pour minimiser la diplopie.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Paralysie</th>\n            <th>Déviation du globe en position primaire</th>\n            <th>Diplopie</th>\n            <th>Signes associés</th>\n            <th>Position vicieuse de la tête</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>III complet</strong></td>\n            <td><span class=\"kw-clinique\">Strabisme externe</span> (œil en abduction par hyperaction du DL — VI conservé) <br><span class=\"kw-clinique\">Œil descendu et dévié en dehors</span> (DI/OS conservés sans antagoniste DS/OI)</td>\n            <td><span class=\"kw-clinique\">Mixte</span> (horizontale croisée par DM + verticale par DS/DI/OI)</td>\n            <td><span class=\"kw-clinique\">Ptosis complet</span> (« providentiel ») <br><span class=\"kw-clinique\">Mydriase aréactive</span> si atteinte intrinsèque associée <br>Paralysie de l'accommodation</td>\n            <td>Souvent <strong>peu marquée</strong> car le ptosis masque la diplopie</td>\n          </tr>\n          <tr>\n            <td><strong>IV</strong></td>\n            <td>Discrète <span class=\"kw-clinique\">hypertropie</span> (œil légèrement plus haut) ± légère extorsion</td>\n            <td><span class=\"kw-clinique\">Diplopie verticale</span>, maximale dans le regard <strong>en bas et en dedans</strong> (gêne à la descente d'escaliers et à la lecture)</td>\n            <td>Aucun ptosis, aucune anomalie pupillaire</td>\n            <td><span class=\"kw-clinique\">Signe de Bielschowski</span> : tête penchée et tournée vers le côté <strong>sain</strong>, menton abaissé (« torticolis oculaire »)</td>\n          </tr>\n          <tr>\n            <td><strong>VI</strong></td>\n            <td><span class=\"kw-clinique\">Strabisme convergent</span> (œil en adduction — ésotropie) par paralysie du DL</td>\n            <td><span class=\"kw-clinique\">Diplopie horizontale homonyme</span>, maximale dans le regard du côté atteint</td>\n            <td>Aucun ptosis, aucune anomalie pupillaire</td>\n            <td>Tête <strong>tournée du côté atteint</strong> (pour soustraire le regard du champ d'action du DL paralysé)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Comment l'examiner ?</h4>\n      <p>L'<strong>inspection</strong> recherche l'attitude vicieuse compensatrice : la tête se positionne spontanément dans le champ d'action du muscle atteint pour compenser la diplopie, créant un <span class=\"kw-def\">torticolis compensateur</span>. L'inspection évalue ensuite la déviation du globe en <strong>position primaire</strong> (tête droite, axe visuel dirigé droit devant vers l'infini). L'<span class=\"kw-def\">étude des reflets cornéens</span> facilite la détection d'une déviation : normalement, <span class=\"kw-clinique\">les</span> reflets d'une source lumineuse se projettent au centre des 2 pupilles ; une déviation se manifeste par un reflet décentré sur l'un des yeux.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeaux d'orientation étiologique à l'inspection.</strong> Toujours rechercher : <span class=\"kw-clinique\">exophtalmie</span>, <span class=\"kw-clinique\">chémosis</span>, <span class=\"kw-clinique\">dilatation en tête de méduse</span> des vaisseaux épiscléraux (FCC ++), <span class=\"kw-clinique\">rétraction palpébrale</span> (Basedow), <span class=\"kw-clinique\">anisocorie / mydriase</span> (atteinte intrinsèque du III), <span class=\"kw-clinique\">ptosis</span> (III ou myasthénie).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération chronique de la vision · 82 — Altération aiguë de la vision</em></p>","frequence":4},{"id":"102-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie/vidéo d’une paralysie du VI","contenu":"<p>À reconnaître au coup d'œil sur une photo/vidéo en position primaire et lors d'une <span class=\"kw-def\">latéroversion</span> du côté atteint.</p>\n\n      <h4>Sémiologie à décrire devant l'image</h4>\n      <ul>\n        <li><strong>En position primaire</strong> : <span class=\"kw-clinique\">ésotropie</span> (œil en adduction, dévié vers le nez) du côté de la paralysie, par hyperaction du <span class=\"kw-def\">droit médial (DM)</span> homolatéral (qui n'a plus son antagoniste DL).</li>\n        <li><strong>Lors de la latéroversion vers le côté atteint</strong> : <span class=\"kw-clinique\">déficit d'abduction</span> de l'œil paralysé qui ne dépasse pas la ligne médiane, contraste majeur avec l'œil sain qui adducte normalement.</li>\n        <li><strong>Reflets cornéens asymétriques</strong> : reflet centré sur l'œil sain, reflet décalé en temporal (dehors) sur l'œil paralysé en adduction.</li>\n        <li><strong>Position vicieuse de la tête</strong> : tournée du <span class=\"kw-clinique\">côté atteint</span> pour minimiser la diplopie.</li>\n        <li><strong>Diplopie horizontale homonyme</strong> au verre rouge : point rouge à droite du point blanc si VI droit, à gauche si VI gauche (cf <em>obj-2</em>).</li>\n        <li><strong>Pas de ptosis, pas d'anomalie pupillaire</strong> — c'est le critère essentiel qui distingue le VI du III.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucun fichier image utilisable n'a été extrait à ce build du dossier <code>fiches sources/102/</code> (<span class=\"kw-clinique\">les</span> PNG présents — schémas anatomiques des nerfs oculomoteurs, image FCC en tête de méduse — n'illustrent pas spécifiquement une paralysie du VI). Kevin pourra déposer une <strong>photo clinique de paralysie du VI</strong> dans <code>assets/images/102/</code> et la référencer dans cet objectif via le bloc <code>&lt;figure class=\"obj-figure\"&gt;</code> canonique.\n      </div>\n      <!-- TODO Kevin : déposer photo-paralysie-vi.{png|jpg} dans assets/images/102/ -->","frequence":0},{"id":"102-8","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie/vidéo d’une paralysie extrinsèque/intrinsèque du III","contenu":"<p>Deux composantes à reconnaître séparément sur la photo/vidéo : la <strong>couche extrinsèque profonde</strong> (motilité + paupière) et la <strong>couche intrinsèque superficielle</strong> (pupille + accommodation). L'atteinte de l'une, de l'autre, ou des deux a une valeur d'orientation étiologique majeure.</p>\n\n      <h4>1 · Paralysie extrinsèque (couche profonde — la plus visible)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Ptosis complet</span> de la paupière supérieure (releveur paralysé) — peut <span class=\"kw-alerte\">masquer la diplopie</span> (« ptosis providentiel »).</li>\n        <li><span class=\"kw-clinique\">Strabisme externe</span> : œil dévié en abduction (hyperaction du DL — VI conservé — par déficit du DM).</li>\n        <li><span class=\"kw-clinique\">Œil descendu et dévié en dehors</span> : DI et OS conservés (innervés par VI et IV) sans antagoniste vertical (DS et OI paralysés).</li>\n        <li>Paralysie de l'adduction, de l'élévation, de l'abaissement.</li>\n        <li>Au verre rouge : <span class=\"kw-clinique\">diplopie horizontale croisée</span> (point rouge à gauche du point blanc si III droit) + composante verticale.</li>\n      </ul>\n\n      <h4>2 · Paralysie intrinsèque (couche superficielle — l'œil)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Mydriase aréactive</span> unilatérale (sphincter irien paralysé) — ou anisocorie à un moindre degré.</li>\n        <li><span class=\"kw-clinique\">Perte de l'accommodation</span> (muscle ciliaire paralysé) → flou de près.</li>\n        <li>Réflexe photomoteur direct <span class=\"kw-bio\">aboli</span>, consensuel préservé sur l'œil controlatéral.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Valeur étiologique cruciale.</strong> Une <span class=\"kw-alerte\">paralysie extrinsèque + intrinsèque douloureuse du III</span> chez un sujet jeune sans <span class=\"kw-etio\">FRCV</span> impose d'évoquer un <span class=\"kw-alerte\">anévrisme de l'a. communicante postérieure ou supraclinoïdien</span> = <strong>HSA imminente</strong> → transfert en neurochirurgie sans attendre l'imagerie (cf <em>obj-10</em>).\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Inversement.</strong> Une <span class=\"kw-clinique\">paralysie extrinsèque pure</span> (<strong>pupille préservée</strong>) chez un sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span> avec <span class=\"kw-etio\">FRCV</span> oriente d'abord vers une <span class=\"kw-etio\">étiologie vasculaire ischémique</span> (microangiopathie diabétique / <span class=\"kw-def\">HTA</span>, <span class=\"kw-clinique\">maladie de Horton</span>) — c'est la règle classique « <strong>pupil-sparing III</strong> ».\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucun fichier image utilisable n'a été extrait à ce build du dossier <code>fiches sources/102/</code> (<span class=\"kw-clinique\">les</span> PNG sont des schémas anatomiques non spécifiques). Kevin pourra déposer une <strong>photo clinique de paralysie du III (extrinsèque ± intrinsèque)</strong> dans <code>assets/images/102/</code> et la référencer ici via le bloc <code>&lt;figure class=\"obj-figure\"&gt;</code> canonique.\n      </div>\n      <!-- TODO Kevin : déposer photo-paralysie-iii-extrinseque.{png|jpg} et photo-paralysie-iii-intrinseque.{png|jpg} dans assets/images/102/ -->","frequence":0},{"id":"102-9","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir que la paralysie du VI a une faible valeur localisatrice","contenu":"<p>La <span class=\"kw-def\">paralysie du VI</span> a une <strong>faible valeur localisatrice</strong> — elle ne permet pas, à elle seule, de prédire le siège de la <span class=\"kw-clinique\">lésion</span> neurologique. Trois particularités anatomiques expliquent cette fragilité :</p>\n\n      <ul>\n        <li><strong>Long trajet intracrânien</strong> : du pont (noyau) jusqu'à l'orbite — le plus long des nerfs oculomoteurs.</li>\n        <li><strong>Trajet le long de la pointe du rocher</strong> : vulnérable à toute <span class=\"kw-alerte\">fracture du rocher</span>.</li>\n        <li><strong>Fixation à la dure-mère</strong> : le nerf est fixé lors de sa perforation durale, ce qui le rend <span class=\"kw-alerte\">vulnérable à la traction du tronc cérébral</span> lors de toute <span class=\"kw-alerte\">HTIC</span>, indépendamment de l'étiologie ou du siège.</li>\n      </ul>\n\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Mécanisme</th><th>Valeur localisatrice ?</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">HTIC</span></strong></td><td>Traction du nerf VI fixé sur la dure-mère par déplacement caudal du tronc cérébral</td><td><span class=\"kw-alerte\">Aucune — l'atteinte du VI n'oriente PAS sur le siège du processus expansif</span></td></tr>\n          <tr><td><strong>Fracture du rocher</strong></td><td>Atteinte directe du nerf le long de la pointe du rocher</td><td>Localise la fracture (contexte traumatique évident)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Méningite</span>, méningoradiculite</strong></td><td>Inflammation de la base du crâne</td><td>Pas localisateur (atteinte des paires crâniennes basses possibles)</td></tr>\n          <tr><td><strong>Atteinte du sinus caverneux</strong></td><td>Tumeur, thrombose, <span class=\"kw-clinique\">fistule</span></td><td>Localise (mais associé à III, IV, V1-V2)</td></tr>\n          <tr><td><strong>Microangiopathie (<span class=\"kw-def\">diabète</span>, <span class=\"kw-def\">HTA</span>, Horton)</strong></td><td>Ischémie du tronc nerveux (<span class=\"kw-def\">vasa nervorum</span>)</td><td>Aucune — atteinte « bête » d'un long nerf</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau pratique.</strong> Devant une paralysie isolée du VI, ne JAMAIS conclure « c'est dans le pont » sans imagerie. Une <span class=\"kw-alerte\">paralysie du VI isolée + céphalées + nausées + œdème papillaire</span> = <strong><span class=\"kw-alerte\">HTIC</span></strong> jusqu'à preuve du contraire → imagerie cérébrale en <span class=\"kw-alerte\">urgence</span> (cf <em>obj-11</em>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalées</span> · 340 — <span class=\"kw-def\">Accident vasculaire cérébral</span></em></p>","frequence":0},{"id":"102-10","rang":"A","rubrique":"Diagnostic positif","titre":"Devant une diplopie, connaître les arguments cliniques en faveur d’une myasthénie","contenu":"<p>La <span class=\"kw-def\">myasthénie</span> (auto-AC anti-récepteurs à l'acétylcholine au niveau de la jonction neuromusculaire) doit être <strong>évoquée de principe</strong> devant toute diplopie binoculaire, même atypique. Trois caractéristiques cliniques sont presque pathognomoniques.</p>\n\n      <h4>1 · Arguments cliniques majeurs en faveur d'une myasthénie</h4>\n      <table >\n        <thead>\n          <tr><th>Argument</th><th>Détail clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Diplopie fluctuante</strong></td>\n            <td>Apparaît ou s'aggrave à l'<span class=\"kw-clinique\">effort</span> et en fin de journée ; <span class=\"kw-clinique\">disparaît au repos</span> et le matin au réveil. Variabilité dans la journée.</td>\n          </tr>\n          <tr>\n            <td><strong>Diplopie non ou mal systématisée</strong></td>\n            <td>Ne correspond pas à une atteinte tronculaire d'un nerf oculomoteur précis — change de direction, de muscle, peut être bilatérale. <span class=\"kw-clinique\">Atteinte multiple, asymétrique, parfois changeante</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Ptosis associé</strong></td>\n            <td>Souvent associé, fluctuant lui aussi (apparaît en fin de journée ou à l'effort), <span class=\"kw-clinique\">bilatéral et asymétrique</span>. Test du <span class=\"kw-def\">glaçon</span> (regagne le ptosis à l'application froid) pathognomonique.</td>\n          </tr>\n          <tr>\n            <td><strong>Indolore</strong></td>\n            <td><span class=\"kw-clinique\">Pas de douleur</span> orbitaire (≠ Tolosa-Hunt, anévrisme communicante post).</td>\n          </tr>\n          <tr>\n            <td><strong>Pas de mydriase</strong></td>\n            <td><span class=\"kw-bio\">Pupilles normales et réactives</span> — la myasthénie n'atteint <strong>jamais</strong> le sphincter irien (cholinergique muscarinique, pas nicotinique). C'est le critère qui exclut une atteinte intrinsèque du III.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes généraux associés</strong></td>\n            <td><span class=\"kw-clinique\">Déficit proximal des membres</span> fluctuant (myasthénie généralisée), <span class=\"kw-clinique\">signes bulbaires</span> (dysphonie, <span class=\"kw-clinique\">dysphagie</span>, troubles de la mastication), <span class=\"kw-clinique\">dyspnée d'effort</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Confirmation diagnostique (rang B)</h4>\n      <ul>\n        <li><strong>Test à la Prost<span class=\"kw-chiffre\">igm</span>ine®</strong> (néostigmine IM) : régression transitoire des symptômes — utile mais <span class=\"kw-alerte\">peut être négatif</span> dans <span class=\"kw-clinique\">les</span> formes oculaires pures.</li>\n        <li><strong>ENMG avec stimulation répétitive</strong> : recherche d'un <span class=\"kw-bio\">bloc neuromusculaire</span> (décrément <span class=\"kw-chiffre\">≥ 10 %</span>). Peut être absent dans <span class=\"kw-clinique\">les</span> formes oculaires pures.</li>\n        <li><strong>AC anti-récepteurs à l'acétylcholine</strong> dans le sérum — <span class=\"kw-alerte\">absents dans 50 % des cas</span> de myasthénie oculaire pure (chercher alors anti-MuSK, anti-LRP4).</li>\n        <li><strong>Recherche d'un thymome associé</strong> par <span class=\"kw-imagerie\">TDM thoracique</span> (systématique).</li>\n        <li><strong>Traitement par anticholinestérasiques</strong> (<span class=\"kw-ttt\">pyridostigmine</span>) : pas toujours efficace dans <span class=\"kw-clinique\">les</span> formes purement oculaires ; les <span class=\"kw-ttt\">corticoïdes</span> sont souvent plus efficaces dans cette forme.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ <span class=\"kw-def\">Diagnostic positif</span> souvent difficile.</strong> Dans la <strong>myasthénie oculaire pure</strong>, <span class=\"kw-clinique\">les</span> 3 examens paracliniques de référence (Prost<span class=\"kw-chiffre\">igm</span>ine, ENMG, AC anti-RACh) peuvent être tous <span class=\"kw-alerte\">négatifs ou non contributifs</span>. Le diagnostic reste alors clinique (fluctuations, test du glaçon, réponse aux <span class=\"kw-ttt\">corticoïdes</span>), et l'<span class=\"kw-imagerie\">IRM</span> cérébrale est faite pour éliminer une autre cause (<span class=\"kw-clinique\">lésion</span> du tronc, OIN, compression du III).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalées</span> · 96 — Myasthénie (cf neuropathies périphériques)</em></p>","frequence":1},{"id":"102-11","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir qu’une paralysie du III aiguë est une urgence vitale","contenu":"<p>Une <span class=\"kw-alerte\">paralysie du III aiguë</span>, surtout si elle associe une atteinte <strong>intrinsèque</strong> (pupille) et <strong>extrinsèque</strong> (motricité + ptosis) avec une <strong>douleur</strong>, doit faire évoquer en <span class=\"kw-alerte\">URGENCE</span> un <span class=\"kw-alerte\">anévrisme intracrânien fissuré</span> = HSA imminente.</p>\n\n      <h4>1 · Le scénario à reconnaître absolument</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Présentation typique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-clinique\">Sujet jeune, absence de FRCV</span> — argument fort pour une cause non vasculaire <span class=\"kw-etio\">ischémique</span>. (Si patient &gt;<span class=\"kw-chiffre\"> 50 ans</span> avec <span class=\"kw-etio\">FRCV</span>, l'étiologie vasculaire <span class=\"kw-etio\">ischémique</span> microangiopathique reste plus probable.)</td>\n          </tr>\n          <tr>\n            <td><strong>Sémiologie oculomotrice</strong></td>\n            <td><span class=\"kw-clinique\">Paralysie extrinsèque + intrinsèque</span> du III (ptosis + strabisme externe + mydriase aréactive) — l'atteinte pupillaire est l'élément-clé qui distingue d'un III <span class=\"kw-etio\">ischémique</span> « pupil-sparing ».</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td><span class=\"kw-clinique\">Céphalées</span> + douleur orbitaire homolatérale — la paralysie est <span class=\"kw-alerte\">annonciatrice d'une fissuration de l'anévrisme</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Artère en cause</strong></td>\n            <td><span class=\"kw-etio\">A. communicante postérieure homolatérale</span> ⭐ ou <span class=\"kw-etio\">supraclinoïdienne</span> (= partie terminale de la carotide interne).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · CAT — <span class=\"kw-alerte\">urgence</span> absolue</h4>\n      <ol>\n        <li><span class=\"kw-alerte\">Transfert immédiat en service de neurochirurgie</span>, <strong>sans attendre</strong> la réalisation d'une <span class=\"kw-imagerie\">angioTDM</span> ou <span class=\"kw-imagerie\">angioIRM</span>.</li>\n        <li>Sur place : <span class=\"kw-imagerie\">angioTDM cérébrale</span> ou <span class=\"kw-imagerie\">angioIRM</span>. Si négatif ou douteux → <span class=\"kw-imagerie\">artériographie cérébrale</span> de confirmation si forte suspicion clinique.</li>\n        <li>Si anévrisme confirmé : <strong>embolisation endovasculaire</strong> ou clipping neurochirurgical en <span class=\"kw-alerte\">urgence</span>.</li>\n      </ol>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ <span class=\"kw-alerte\">Risque vital</span>.</strong> Toute paralysie complète douloureuse du III chez un sujet jeune = HSA imminente jusqu'à preuve du contraire. <span class=\"kw-alerte\">Ne pas traîner à l'imagerie ambulatoire</span> — le <span class=\"kw-alerte\">pronostic vital</span> est en jeu (<span class=\"kw-def\">mortalité</span> de l'HSA fissurée =<span class=\"kw-chiffre\"> 50 %</span> à<span class=\"kw-chiffre\"> 1 mois</span>). Cf item 341 (Hémorragie méningée).\n      </div>\n\n      <h4>3 · Diagnostics différentiels d'<span class=\"kw-alerte\">urgence</span> devant une diplopie</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">AVC</span> du tronc cérébral</strong> (syndrome alterne) — <span class=\"kw-imagerie\">IRM</span> cérébrale en <span class=\"kw-alerte\">urgence</span>.</li>\n        <li><strong>Encéphalopathie de Gayet-Wernicke</strong> chez l'alcoolique chronique — <span class=\"kw-ttt\">vitamine B1 IV</span> systématique avant toute perfusion glucosée.</li>\n        <li><strong><span class=\"kw-clinique\">Maladie de Horton</span></strong> chez &gt;<span class=\"kw-chiffre\"> 50 ans</span> — <span class=\"kw-ttt\">corticothérapie en urgence</span> avant la <span class=\"kw-bio\">biopsie</span> d'a. temporale (risque de cécité par NOIAA controlatérale).</li>\n        <li><strong>Sinusite sphénoïdale aiguë <span class=\"kw-etio\">fongique</span> invasive</strong> chez l'immunodéprimé — <span class=\"kw-alerte\">pronostic très sombre</span>.</li>\n        <li><strong>Apoplexie pituitaire</strong> : <span class=\"kw-clinique\">céphalées</span> violentes + diplopie + <span class=\"kw-def\">syndrome méningé</span> non fébrile.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-def\">Accident vasculaire cérébral</span> · 341 — Hémorragie méningée</em></p>","frequence":0},{"id":"102-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une diplopie aiguë récente","contenu":"<p>Devant toute <strong>diplopie binoculaire aiguë récente</strong>, l'imagerie est <strong>quasi-systématique</strong> — la stratégie est dictée par le contexte (traumatique <span class=\"kw-bio\">vs</span> non traumatique) et par l'âge / <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">FRCV</span>.</p>\n\n      <h4>1 · Diplopie en contexte traumatique</h4>\n      <table >\n        <thead>\n          <tr><th>Suspicion</th><th>Imagerie de 1<sup>re</sup> intention</th><th>Signes recherchés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Traumatisme orbitaire</strong> (fracture du plancher en trappe ++)</td>\n            <td><span class=\"kw-imagerie\">TDM cérébrale en urgence</span> + coupes orbitaires en séquences osseuses</td>\n            <td><span class=\"kw-clinique\">Incarcération du muscle droit inférieur</span> dans le foyer de fracture → image en « <span class=\"kw-imagerie\">goutte dans le sinus maxillaire</span> » (hernie graisseuse et musculaire) <br><strong>Test de duction forcée</strong> : mobilisation passive du globe par traction du DI impossible</td>\n          </tr>\n          <tr>\n            <td><strong>Traumatisme crânien sévère + <span class=\"kw-alerte\">HTIC</span></strong></td>\n            <td><span class=\"kw-imagerie\">TDM cérébrale en urgence</span></td>\n            <td><span class=\"kw-clinique\">Lésion</span> expansive, hématome, <span class=\"kw-clinique\">œdème</span> cérébral → atteinte <span class=\"kw-clinique\">bilatérale du VI</span> par <span class=\"kw-alerte\">HTIC</span> ; atteinte du IV, plus rarement du III</td>\n          </tr>\n          <tr>\n            <td><strong>Traumatisme crânien bénin</strong></td>\n            <td><span class=\"kw-imagerie\">TDM cérébrale</span> (recherche d'une fracture occulte du rocher si atteinte du VI)</td>\n            <td>Atteinte isolée du <span class=\"kw-clinique\">IV</span> classique, sans autre complication neurologique (le IV est le plus fragile)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Diplopie non traumatique</h4>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Imagerie</th><th>Justification</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Paralysie du III aiguë douloureuse</strong> (extrinsèque + intrinsèque)</td>\n            <td><span class=\"kw-imagerie\">AngioTDM ou angioIRM cérébrale</span> en <span class=\"kw-alerte\">urgence</span>, ± <span class=\"kw-imagerie\">artériographie</span> si forte suspicion</td>\n            <td>Rechercher un <span class=\"kw-alerte\">anévrisme de la communicante postérieure ou supraclinoïdien</span> = HSA imminente (cf <em>obj-10</em>)</td>\n          </tr>\n          <tr>\n            <td><strong>Diplopie + syndrome orbitaire</strong> (exophtalmie, chémosis)</td>\n            <td><span class=\"kw-imagerie\">TDM ou IRM cérébrale</span> centrée sur <span class=\"kw-clinique\">les</span> orbites</td>\n            <td>Rechercher : <strong>orbitopathie dysthyroïdienne</strong> (augmentation de volume des muscles orbitaires), <strong>FCC</strong> (dilatation veines ophtalmiques), <strong>tumeur de l'orbite</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion d'OIN, <span class=\"kw-def\">AVC</span> du tronc, SEP</strong></td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> avec séquences <span class=\"kw-imagerie\">FLAIR</span> + <span class=\"kw-imagerie\">diffusion</span> + T<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>ado</td>\n            <td>Plaques de démyélinisation (SEP &lt;<span class=\"kw-chiffre\"> 40 ans</span>), lacune du tronc cérébral (&gt;<span class=\"kw-chiffre\"> 50 ans</span> avec <span class=\"kw-etio\">FRCV</span>), tumeur</td>\n          </tr>\n          <tr>\n            <td><strong>Diplopie + syndrome caverneux</strong> (atteinte III + IV + V1-V2 + VI)</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> avec coupes injectées centrées sur le sinus caverneux</td>\n            <td>Rechercher : <strong>Tolosa-Hunt</strong> (inflammation), <strong>méningiome</strong>, <strong>extension d'adénome hypophysaire</strong>, <strong>thrombose</strong>, <strong>FCC</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Diplopie + ataxie / <span class=\"kw-clinique\">vertige</span> / <span class=\"kw-clinique\">paresthésies</span></strong></td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> en <span class=\"kw-alerte\">urgence</span> (suspicion <span class=\"kw-def\">AIT</span>/<span class=\"kw-def\">AVC</span> vertébrobasilaire) + <span class=\"kw-imagerie\">écho-doppler TSAO</span> + <span class=\"kw-imagerie\">polygone de Willis</span> + <span class=\"kw-bio\">ECG</span></td>\n            <td>Diplopie présente dans <span class=\"kw-chiffre\">30 %</span> des insuffisances vertébrobasilaires (cf <em>obj-13</em>)</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion de méningoradiculite</strong> (Lyme, <span class=\"kw-def\">AIT</span> vertébrobasilaire normal)</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> normale → <span class=\"kw-bio\">PL avec étude du LCS</span></td>\n            <td>Lymphocytose, hyperprotéinorachie, <span class=\"kw-bio\">sérologie</span> Lyme (ELISA + Western Blot) sang et <span class=\"kw-bio\">LCS</span></td>\n          </tr>\n          <tr>\n            <td><strong>Paralysie extrinsèque pure du III</strong> chez &gt;<span class=\"kw-chiffre\"> 50 ans</span> avec <span class=\"kw-etio\">FRCV</span></td>\n            <td>Bilan <span class=\"kw-ttt\">biologique</span> en 1<sup>re</sup> intention : <span class=\"kw-bio\">NFS-plaquettes, VS, CRP, glycémie, HbA1c</span> → <span class=\"kw-imagerie\">IRM</span> si pas d'amélioration à<span class=\"kw-chiffre\"> 3 mois</span></td>\n            <td>Évoquer microangiopathie (<span class=\"kw-def\">diabète</span>, <span class=\"kw-def\">HTA</span>) ou <span class=\"kw-etio\">maladie de Horton</span> +++</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Règle générale.</strong> Le <span class=\"kw-imagerie\">scanner</span> sans injection est l'examen de débrouillage en contexte traumatique ou en <span class=\"kw-alerte\">urgence</span> vitale (HSA, <span class=\"kw-def\"><span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">hémorragique</span></span>). L'<span class=\"kw-imagerie\">IRM cérébrale</span> est l'examen de référence pour explorer le tronc cérébral, le sinus caverneux et le parenchyme (SEP, lacune, tumeur, Tolosa-Hunt). L'<span class=\"kw-imagerie\">angioscanner / angioIRM</span> sont indispensables dès que l'on suspecte une cause vasculaire (anévrisme, FCC, <span class=\"kw-etio\">dissection</span>).\n      </div>","frequence":2},{"id":"102-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les causes ophtalmologiques de diplopie monoculaire","contenu":"<p>La <span class=\"kw-def\">diplopie monoculaire</span> (= persiste à l'occlusion de l'œil sain) est <strong>toujours d'origine ophtalmologique</strong> — par trouble de la diffraction des rayons lumineux entre la cornée et la rétine. <strong>Aucune <span class=\"kw-alerte\">urgence</span> neurologique</strong> : l'examen ophtalmologique se fait en consultation programmée.</p>\n\n      <table >\n        <thead>\n          <tr><th>Site anatomique</th><th>Mécanisme</th><th>Étiologies à connaître</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cornée</strong> (la plus fréquente)</td>\n            <td>Diffraction anormale des rayons lumineux</td>\n            <td><span class=\"kw-etio\">Astigmatisme important</span> (irrégularité de la courbure cornéenne) <br><span class=\"kw-etio\">Kératocône</span> (déformation conique progressive de la cornée) <br><span class=\"kw-etio\">Taie cornéenne</span> (séquelle d'une kératite ou d'un traumatisme — opacité cicatricielle)</td>\n          </tr>\n          <tr>\n            <td><strong>Iris</strong></td>\n            <td>Double pupille fonctionnelle</td>\n            <td><span class=\"kw-etio\">Iridodialyse traumatique</span> (désinsertion de l'iris à sa base après contusion oculaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Cristallin</strong></td>\n            <td>Trouble de la réfraction par opacité hétérogène ou décentrement</td>\n            <td><span class=\"kw-etio\">Cataracte nucléaire</span> (opacité du noyau cristallinien créant 2 indices de réfraction) <br><span class=\"kw-etio\">Implant intraoculaire décentré</span> (post-<span class=\"kw-ttt\">chirurgie</span> de cataracte)</td>\n          </tr>\n          <tr>\n            <td><strong>Macula</strong> (rarement)</td>\n            <td>Distorsion mécanique du tissu rétinien</td>\n            <td><span class=\"kw-etio\">Membrane épirétinienne tractionnelle</span> (pucker maculaire, traction vitréo-rétinienne)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT pratique.</strong> Devant une diplopie monoculaire : <span class=\"kw-clinique\">examen ophtalmologique sans urgence</span>. <br>1. Acuité visuelle avec et sans correction. <br>2. Examen à la <strong>lampe à fente</strong> : cornée, chambre antérieure, iris, cristallin. <br>3. <strong><span class=\"kw-imagerie\">Fond d'œil</span></strong> : recherche de membrane épirétinienne. <br>4. <strong>Topographie cornéenne</strong> si suspicion d'ast<span class=\"kw-chiffre\">igm</span>atisme irrégulier ou de kératocône. <br>5. Si l'examen est normal → évoquer une <span class=\"kw-clinique\">cause fonctionnelle</span> (rare).\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Piège.</strong> Une diplopie peut être <strong>mixte</strong> (mono + binoculaire) — typiquement chez un sujet âgé qui cumule cataracte (monoculaire) et microangiopathie diabétique (binoculaire). Toujours faire le test de l'occlusion sur <strong>chaque œil séparément</strong> et noter la persistance/disparition.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 85 — Troubles de la réfraction · 81 — Altération chronique de la vision</em></p>","frequence":1},{"id":"102-14","rang":"B","rubrique":"Étiologies","titre":"Devant une diplopie, savoir rechercher les principaux signes associés à valeur étiologique","contenu":"<p>Le bilan étiologique d'une diplopie binoculaire repose sur la <strong>recherche systématique de signes associés</strong> à l'interrogatoire et à l'examen. Cette grille est <em>discriminante</em> : un seul signe peut orienter vers l'étiologie urgente à traiter.</p>\n\n      <h4>1 · Interrogatoire — <span class=\"kw-clinique\">les</span> 5 axes systématiques</h4>\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Éléments à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>âge ; antécédents oculaires et généraux ; <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">maladie thyroïdienne</span>, maladie métabolique ou endocrinienne</td></tr>\n          <tr><td><strong>Circonstances de survenue</strong></td><td><span class=\"kw-etio\">traumatisme</span>, survenue lors d'un effort physique, à la lecture, à la fatigue</td></tr>\n          <tr><td><strong>Mode de survenue</strong></td><td>brutal <span class=\"kw-bio\">vs</span> progressif ; constant <span class=\"kw-bio\">vs</span> fluctuant ; transitoire <span class=\"kw-bio\">vs</span> permanent</td></tr>\n          <tr><td><strong>Symptômes associés</strong></td><td><span class=\"kw-clinique\">douleurs</span>, <span class=\"kw-clinique\">vertiges</span>, <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">nausées</span></td></tr>\n          <tr><td><strong>Caractères de la diplopie</strong></td><td>horizontale, verticale, oblique ; position du regard dans laquelle elle est <strong>maximale</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Examen orienté — signes drapeaux à rechercher</h4>\n      <table >\n        <thead>\n          <tr><th>Signe associé</th><th>Étiologie évoquée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Exophtalmie + chémosis + rétraction palpébrale bilatérale</span></td><td><span class=\"kw-etio\">Orbitopathie dysthyroïdienne / Basedow</span> — <span class=\"kw-bio\">bilan thyroïdien</span> + AC anti-RTSH + <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> orbites (augmentation de volume des muscles oculomoteurs)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Exophtalmie pulsatile + souffle systolo-diastolique + dilatation en tête de méduse</span></td><td><span class=\"kw-etio\">Fistule carotido-caverneuse (FCC)</span>, souvent post-traumatique mais d'apparition retardée — <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> (dilatation veine sus-orbitaire) puis <span class=\"kw-imagerie\">artériographie</span> de confirmation, traitement par embolisation</td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie d'installation progressive + exophtalmie isolée</span></td><td><span class=\"kw-etio\">Tumeur de l'orbite</span> — <span class=\"kw-imagerie\">IRM</span>/<span class=\"kw-imagerie\">TDM</span> centrée sur <span class=\"kw-clinique\">les</span> orbites</td></tr>\n          <tr><td><span class=\"kw-clinique\">Céphalées + paralysie VI + nausées + œdème papillaire</span></td><td><span class=\"kw-alerte\">HTIC</span> — <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> cérébrale en <span class=\"kw-alerte\">urgence</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Céphalées violentes + syndrome méningé non fébrile + diplopie</span></td><td><span class=\"kw-etio\">Hémorragie méningée, Apoplexie pituitaire</span> — <span class=\"kw-imagerie\">TDM</span> cérébrale en <span class=\"kw-alerte\">urgence</span> ± PL</td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie + ataxie</span></td><td><span class=\"kw-alerte\">AVC vertébrobasilaire</span> (à évoquer en <span class=\"kw-alerte\">urgence</span>), <span class=\"kw-etio\">syndrome de Miller-Fisher</span> (polyradiculonévrite aiguë avec ophtalmoplégie bilatérale + ataxie sensorielle + aréflexie), <span class=\"kw-etio\">encéphalopathie de Gayet-Wernicke</span> chez l'alcoolique chronique</td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie + syndrome alterne</span> (<span class=\"kw-clinique\">hémiplégie</span> / hémianesthésie controlatérale)</td><td><span class=\"kw-etio\">Atteinte du tronc cérébral</span> — causes vasculaires, tumorales, inflammatoires (<span class=\"kw-clinique\">syndrome de Weber</span> = III + <span class=\"kw-clinique\">hémiplégie</span> croisée)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Placard érythémateux migrant + morsure de tique récente + atteinte des paires crâniennes</span></td><td><span class=\"kw-etio\">Méningoradiculite de Lyme</span> — <span class=\"kw-bio\">sérologie</span> ELISA + Western Blot sang/<span class=\"kw-bio\">LCS</span>, <span class=\"kw-ttt\">ceftriaxone 2 g/j × 15-21 j</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Éruption vésiculeuse en V1 chez &gt; 50 ans</span></td><td><span class=\"kw-etio\">Zona ophtalmique</span> — <span class=\"kw-ttt\">valaciclovir per os 7 j</span> dans <span class=\"kw-clinique\">les</span> &lt;<span class=\"kw-chiffre\"> 72 h</span>, paralysie oculomotrice généralement régressive</td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie fluctuante + ptosis bilatéral asymétrique + déficit proximal des membres</span></td><td><span class=\"kw-etio\">Myasthénie généralisée</span> (cf <em>obj-9</em>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie + céphalées d'orthostatisme</span></td><td><span class=\"kw-etio\">Hypotension intracrânienne</span> — atteinte uni- ou bilatérale du IV</td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie + immunodéprimé + sinusite</span></td><td><span class=\"kw-alerte\">Sinusite sphénoïdale aiguë fongique invasive</span> — <span class=\"kw-def\">pronostic</span> très sombre, <span class=\"kw-alerte\">urgence</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Diplopie aiguë inaugurale et transitoire (&lt; 1 h)</span></td><td><span class=\"kw-alerte\">AIT vertébrobasilaire</span> (présent dans <span class=\"kw-chiffre\">30 %</span> des cas, parfois symptôme unique) — <span class=\"kw-imagerie\">IRM</span> + <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span> TSAO + polygone de Willis + bilan Horton + <span class=\"kw-bio\">ECG</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Étiologies à évoquer selon la sémiologie du III</h4>\n      <table >\n        <thead>\n          <tr><th>Présentation du III</th><th>Si &gt;<span class=\"kw-chiffre\"> 50 ans</span> avec <span class=\"kw-etio\">FRCV</span></th><th>Si &lt;<span class=\"kw-chiffre\"> 50 ans</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Paralysie intrinsèque + extrinsèque + douloureuse</strong></td>\n            <td colspan=\"2\"><span class=\"kw-alerte\">Anévrisme communicante postérieure ou supraclinoïdien</span> = HSA imminente — <span class=\"kw-alerte\">urgence</span> neurochirurgicale (cf <em>obj-10</em>)</td>\n          </tr>\n          <tr>\n            <td><strong>Paralysie extrinsèque pure (pupille épargnée)</strong></td>\n            <td><span class=\"kw-etio\">Étiologie vasculaire ischémique</span> 🔥 : <span class=\"kw-etio\">maladie de Horton</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-def\">HTA</span> (microangiopathie). Bilan : <span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">HbA1c</span></td>\n            <td>Causes <span class=\"kw-etio\">inflammatoires, compressives, infiltratives</span> ; <span class=\"kw-etio\">syndrome de Tolosa-Hunt</span> (inflammation douloureuse du sinus caverneux, récidivante, alternante, cortico-sensible). Bilan : <span class=\"kw-imagerie\">IRM</span> cérébrale injectée centrée sur le sinus caverneux + PL</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 470\" role=\"img\" aria-label=\"Arbre d'orientation étiologique d'une diplopie binoculaire. Première question : la diplopie est-elle douloureuse ? Si elle est douloureuse avec une atteinte pupillaire, c'est-à-dire une paralysie du III à la fois intrinsèque et extrinsèque, il faut évoquer en urgence un anévrisme de l'artère communicante postérieure ou supraclinoïdien, équivalent à une hémorragie sous-arachnoïdienne imminente, justifiant un transfert immédiat en neurochirurgie. Si elle est douloureuse sans atteinte pupillaire, on évoque selon le terrain un syndrome de Tolosa-Hunt, une dissection carotidienne, ou une maladie de Horton chez le sujet de plus de 50 ans. Si la diplopie n'est pas douloureuse, deuxième question : quel est l'âge et y a-t-il des facteurs de risque cardiovasculaire ? Après 50 ans avec facteurs de risque cardiovasculaire, on évoque d'abord une cause microvasculaire ischémique par atteinte des vasa nervorum, c'est-à-dire diabète ou hypertension, et il faut systématiquement éliminer une maladie de Horton. Avant 40 ans, devant une ophtalmoplégie internucléaire, on évoque une sclérose en plaques. À tout âge, il faut évoquer une myasthénie oculaire pure et une tumeur. Une atteinte du VI est de faible valeur localisatrice et impose de rechercher une hypertension intracrânienne.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Diplopie binoculaire — orientation étiologique</text>\n\n          <rect class=\"fb-grey\" x=\"194\" y=\"30\" width=\"172\" height=\"34\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"51\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Diplopie douloureuse ?</text>\n\n          <!-- branche OUI (gauche) -->\n          <line class=\"ln\" x1=\"280\" y1=\"64\" x2=\"280\" y2=\"76\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"140\" y1=\"76\" x2=\"420\" y2=\"76\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"140\" y1=\"76\" x2=\"140\" y2=\"88\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"140,94 135,86 145,86\"/>\n          <line class=\"ln\" x1=\"420\" y1=\"76\" x2=\"420\" y2=\"88\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"420,94 415,86 425,86\"/>\n          <text class=\"tx-muted\" x=\"124\" y=\"88\" text-anchor=\"end\" font-size=\"10\" font-weight=\"700\">OUI</text>\n          <text class=\"tx-muted\" x=\"436\" y=\"88\" text-anchor=\"start\" font-size=\"10\" font-weight=\"700\">NON</text>\n\n          <!-- sous-question pupille (gauche) -->\n          <rect class=\"fb-grey\" x=\"24\" y=\"96\" width=\"232\" height=\"32\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"140\" y=\"116\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Atteinte pupillaire (III intrins.) ?</text>\n          <line class=\"ln\" x1=\"140\" y1=\"128\" x2=\"140\" y2=\"138\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"72\" y1=\"138\" x2=\"208\" y2=\"138\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"72\" y1=\"138\" x2=\"72\" y2=\"150\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"72,156 67,148 77,148\"/>\n          <line class=\"ln\" x1=\"208\" y1=\"138\" x2=\"208\" y2=\"150\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"208,156 203,148 213,148\"/>\n          <text class=\"tx-muted\" x=\"60\" y=\"150\" text-anchor=\"end\" font-size=\"9\" font-weight=\"700\">OUI</text>\n          <text class=\"tx-muted\" x=\"220\" y=\"150\" text-anchor=\"start\" font-size=\"9\" font-weight=\"700\">NON</text>\n\n          <rect class=\"fb-red\" x=\"14\" y=\"158\" width=\"120\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"74\" y=\"176\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Anévrisme comm.</text>\n          <text class=\"tx-red\" x=\"74\" y=\"189\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">post. (HSA)</text>\n          <text class=\"tx-red\" x=\"74\" y=\"205\" text-anchor=\"middle\" font-size=\"8.5\"><span class=\"kw-alerte\">URGENCE</span> neurochir.</text>\n\n          <rect class=\"fb-amber\" x=\"146\" y=\"158\" width=\"120\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"206\" y=\"174\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Tolosa-Hunt,</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"187\" text-anchor=\"middle\" font-size=\"9.5\"><span class=\"kw-etio\">dissection</span> carotid.</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"203\" text-anchor=\"middle\" font-size=\"9\">Horton si &gt;<span class=\"kw-chiffre\"> 50 ans</span></text>\n\n          <!-- sous-question âge (droite) -->\n          <rect class=\"fb-grey\" x=\"304\" y=\"96\" width=\"232\" height=\"32\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"420\" y=\"116\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Âge &gt;<span class=\"kw-chiffre\"> 50 ans</span> + <span class=\"kw-etio\">FRCV</span> ?</text>\n          <line class=\"ln\" x1=\"420\" y1=\"128\" x2=\"420\" y2=\"138\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"352\" y1=\"138\" x2=\"488\" y2=\"138\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"352\" y1=\"138\" x2=\"352\" y2=\"150\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"352,156 347,148 357,148\"/>\n          <line class=\"ln\" x1=\"488\" y1=\"138\" x2=\"488\" y2=\"150\" stroke-width=\"2\"/><polygon class=\"ah\" points=\"488,156 483,148 493,148\"/>\n          <text class=\"tx-muted\" x=\"340\" y=\"150\" text-anchor=\"end\" font-size=\"9\" font-weight=\"700\">OUI</text>\n          <text class=\"tx-muted\" x=\"500\" y=\"150\" text-anchor=\"start\" font-size=\"9\" font-weight=\"700\">NON</text>\n\n          <rect class=\"fb-amber\" x=\"294\" y=\"158\" width=\"120\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"354\" y=\"174\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Microvasculaire</text>\n          <text class=\"tx-amber\" x=\"354\" y=\"187\" text-anchor=\"middle\" font-size=\"9\"><span class=\"kw-etio\">diabète</span> / HTA</text>\n          <text class=\"tx-amber\" x=\"354\" y=\"203\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\">éliminer Horton</text>\n\n          <rect class=\"fb-purple\" x=\"426\" y=\"158\" width=\"120\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"486\" y=\"174\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">&lt;<span class=\"kw-chiffre\"> 40 ans</span> + OIN</text>\n          <text class=\"tx-purple\" x=\"486\" y=\"187\" text-anchor=\"middle\" font-size=\"9.5\">→ SEP</text>\n          <text class=\"tx-purple\" x=\"486\" y=\"203\" text-anchor=\"middle\" font-size=\"8.5\">tumeur, myasthénie</text>\n\n          <!-- bandeaux transverses -->\n          <rect class=\"fb-blue\" x=\"24\" y=\"234\" width=\"512\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"251\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">À évoquer de principe À TOUT ÂGE devant une diplopie binoculaire isolée</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"267\" text-anchor=\"middle\" font-size=\"9.5\">Myasthénie oculaire pure · tumeur · atteinte microvasculaire</text>\n\n          <rect class=\"fb-red\" x=\"24\" y=\"284\" width=\"512\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"301\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Paralysie du VI = faible valeur localisatrice</text>\n          <text class=\"tx-red\" x=\"280\" y=\"317\" text-anchor=\"middle\" font-size=\"9.5\">VI isolé + <span class=\"kw-clinique\">céphalées</span> + <span class=\"kw-clinique\">œdème</span> papillaire → <span class=\"kw-alerte\">HTIC</span> jusqu'à preuve du contraire</text>\n\n          <!-- signes drapeaux orbitaires -->\n          <text class=\"tx-title\" x=\"280\" y=\"346\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Drapeaux orbitaires associés (examen)</text>\n          <rect class=\"fb-amber\" x=\"24\" y=\"354\" width=\"166\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"107\" y=\"372\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Exophtalmie bilat. +</text>\n          <text class=\"tx-amber\" x=\"107\" y=\"389\" text-anchor=\"middle\" font-size=\"9\">rétraction palpébr. → Basedow</text>\n          <rect class=\"fb-red\" x=\"197\" y=\"354\" width=\"166\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"372\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Exophtalmie pulsatile +</text>\n          <text class=\"tx-red\" x=\"280\" y=\"389\" text-anchor=\"middle\" font-size=\"9\">souffle, tête de méduse → FCC</text>\n          <rect class=\"fb-grey\" x=\"370\" y=\"354\" width=\"166\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"453\" y=\"370\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Diplopie + ataxie →</text>\n          <text class=\"tx-grey\" x=\"453\" y=\"383\" text-anchor=\"middle\" font-size=\"9\"><span class=\"kw-alerte\">AVC</span> vertébrobasilaire,<tspan x=\"453\" dy=\"12\">Miller-Fisher</tspan></text>\n\n          <rect class=\"fb-ok\" x=\"24\" y=\"412\" width=\"512\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"280\" y=\"430\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Traitement symptomatique (toute étiologie)</text>\n          <text class=\"tx-ok\" x=\"280\" y=\"446\" text-anchor=\"middle\" font-size=\"9.5\">Occlusion œil paralysé · prismation · PAS de rééducation orthoptique</text>\n        </svg>\n        <figcaption>Trois questions hiérarchisées orientent la diplopie binoculaire : <strong>douleur</strong>, <strong>atteinte pupillaire</strong> (III intrinsèque), <strong>âge / FRCV</strong>. Le scénario rouge — III douloureux à pupille atteinte — impose un transfert neurochirurgical immédiat (anévrisme = HSA imminente).</figcaption>\n      </figure>\n\n      <h4>4 · Diplopies douloureuses — étiologies clés</h4>\n      <ul>\n        <li><strong>Vasculaire :</strong> anévrisme de l'a. communicante postérieure ou supraclinoïdien ; <span class=\"kw-etio\">dissection carotidienne</span> ; FCC ; <span class=\"kw-def\">diabète</span>, Horton.</li>\n        <li><strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-def\">tuberculose</span>, brucellose.</li>\n        <li><strong><span class=\"kw-etio\">Tumoral</span> :</strong> tumeur du sinus caverneux (<span class=\"kw-etio\">méningiome</span>, extension d'<span class=\"kw-etio\">adénome hypophysaire</span>) ; <span class=\"kw-ttt\">infiltration</span> carcinomateuse de la base du crâne.</li>\n        <li><strong><span class=\"kw-etio\">Inflammatoire</span> :</strong> <span class=\"kw-etio\">Tolosa-Hunt</span>, <span class=\"kw-etio\">sarcoïdose</span>.</li>\n      </ul>\n\n      <h4>5 · Diplopie binoculaire isolée (pas de signe associé, pas de douleur)</h4>\n      <p>Quatre étiologies à connaître par cœur dans cette situation diagnostique difficile :</p>\n      <ul>\n        <li><strong>OIN isolée :</strong> <span class=\"kw-alerte\">SEP avant 40 ans</span>, <span class=\"kw-alerte\">lacune du tronc cérébral après 50 ans avec FRCV</span>.</li>\n        <li><strong>Myasthénie oculaire pure :</strong> toujours à évoquer de principe (cf <em>obj-9</em>) — <span class=\"kw-ttt\">corticoïdes</span> souvent plus efficaces que <span class=\"kw-clinique\">les</span> anticholinestérasiques.</li>\n        <li><strong>Tumeur :</strong> à évoquer à tout âge — <span class=\"kw-imagerie\">IRM</span> cérébrale.</li>\n        <li><strong>Atteinte microvasculaire :</strong> cause la plus fréquente chez &gt;<span class=\"kw-chiffre\"> 70 ans</span> et chez <span class=\"kw-clinique\">les</span> patients diabétiques (atteinte des <span class=\"kw-def\">vasa nervorum</span>). CAT : rechercher/équilibrer tous les <span class=\"kw-etio\">FRCV</span>, éliminer une <span class=\"kw-etio\">artérite giganto-cellulaire</span> (Horton).</li>\n      </ul>\n\n      <h4>6 · Traitement symptomatique de la diplopie (indépendamment de l'étiologie)</h4>\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Traitement</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Phase précoce (1<sup>ers</sup> mois)</strong></td><td><span class=\"kw-ttt\">Occlusion de l'œil paralysé</span> (Opticlude®, Ocusert®) — suppression du confort de la diplopie. <br><span class=\"kw-ttt\">Prismation</span> sur un verre de lunette lorsque cela est possible — rétablit le parallélisme des rayons lumineux, supprime la diplopie au moins en position primaire. <br><em>Injection de toxine botulique</em> (notamment paralysie du VI post-traumatique, rang C).</td></tr>\n          <tr><td><strong>Non indiqué</strong></td><td><span class=\"kw-ci\">Pas de rééducation orthoptique</span> — favoriserait <span class=\"kw-clinique\">les</span> hyperactions compensatrices.</td></tr>\n          <tr><td><em>Phase tardive (rang C)</em></td><td><em>Régénérescence nerveuse attendue en <span class=\"kw-chiffre\">6 mois</span> à<span class=\"kw-chiffre\"> 1 an</span>. Passé ce délai, traitement <span class=\"kw-ttt\">chirurgical</span> envisageable pour rétablir un parallélisme au moins en position primaire.</em></td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 104 — <span class=\"kw-ttt\">Sclérose</span> en plaques · 100 — <span class=\"kw-clinique\">Céphalées</span> · 340 — <span class=\"kw-def\">Accident vasculaire cérébral</span> · 341 — Hémorragie méningée</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>1er geste :</strong> <span class=\"kw-clinique\">occlusion alternée d'un œil</span> — une diplopie <span class=\"kw-def\">binoculaire</span> (disparaît quel que soit l'œil occlus) est <span class=\"kw-alerte\">neurologique ou orbitaire, souvent urgente</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> vitale :</strong> une <span class=\"kw-alerte\">paralysie du III aiguë avec mydriase et/ou douleur</span> fait évoquer un <span class=\"kw-etio\">anévrisme de l'a. communicante postérieure</span> → <span class=\"kw-alerte\">HSA imminente</span>.<br><strong>Délai anévrisme :</strong> <span class=\"kw-ttt\">transfert en neurochirurgie immédiat</span>, <span class=\"kw-chiffre\">sans attendre</span> l'<span class=\"kw-imagerie\">angioTDM</span>/<span class=\"kw-imagerie\">angioIRM</span>.<br><strong>Contexte traumatique :</strong> <span class=\"kw-imagerie\">TDM cérébrale</span> en urgence en <span class=\"kw-chiffre\">1re intention</span> dans tous <span class=\"kw-clinique\">les</span> cas.<br><strong>Diplopie transitoire :</strong> survenue brutale, <span class=\"kw-chiffre\">&lt; 1 h</span>, régressive → évoquer un <span class=\"kw-etio\">AIT vertébrobasilaire</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> diplopie <span class=\"kw-def\">monoculaire</span> → <span class=\"kw-ttt\">consultation ophtalmologique programmée</span>, sans <span class=\"kw-alerte\">urgence</span>.<br><strong>Neurochirurgie (immédiat) :</strong> <span class=\"kw-clinique\">paralysie du III intrinsèque + extrinsèque douloureuse</span> → <span class=\"kw-ttt\">transfert sans attendre l'imagerie</span> (<span class=\"kw-etio\">anévrisme</span>).<br><strong>Urgence neurologique :</strong> diplopie binoculaire aiguë avec <span class=\"kw-alerte\">signes de gravité</span> → <span class=\"kw-imagerie\">imagerie cérébrale en urgence</span> + avis spécialisé.<br><strong>Bilan orienté :</strong> diplopie binoculaire <span class=\"kw-clinique\">isolée</span> → bilan étiologique selon l'âge (myasthénie, OIN, microvasculaire).</p>","redflags":"<ul><li><span class=\"kw-clinique\">Mydriase + paralysie du III douloureuse</span> → <span class=\"kw-etio\">anévrisme de l'a. communicante postérieure</span> (<span class=\"kw-alerte\">HSA imminente</span>)</li><li><span class=\"kw-clinique\">Diplopie + ataxie</span> → <span class=\"kw-etio\">AVC du tronc cérébral</span>, <span class=\"kw-etio\">syndrome de Miller-Fisher</span> ou <span class=\"kw-etio\">encéphalopathie de Gayet-Wernicke</span></li><li><span class=\"kw-clinique\">Céphalées + paralysie du VI + nausées + œdème papillaire</span> → <span class=\"kw-etio\">HTIC</span></li><li><span class=\"kw-clinique\">Céphalées violentes + syndrome méningé non fébrile</span> → <span class=\"kw-etio\">hémorragie méningée / apoplexie pituitaire</span></li><li><span class=\"kw-clinique\">Exophtalmie pulsatile + souffle + chémosis en « tête de méduse »</span> → <span class=\"kw-etio\">fistule carotido-caverneuse</span></li><li><span class=\"kw-etio\">Sinusite sphénoïdale aiguë fongique invasive</span> chez l'<span class=\"kw-clinique\">immunodéprimé</span> (<span class=\"kw-alerte\">pronostic très sombre</span>)</li><li>Sujet <span class=\"kw-chiffre\">&gt; 50 ans</span> avec <span class=\"kw-clinique\">paralysie extrinsèque</span> → éliminer une <span class=\"kw-etio\">maladie de Horton</span> (<span class=\"kw-alerte\">urgence</span> dans tous <span class=\"kw-clinique\">les</span> cas)</li><li><span class=\"kw-clinique\">Diplopie brutale transitoire</span>, <span class=\"kw-chiffre\">&lt; 1 h</span> → <span class=\"kw-etio\">AIT vertébrobasilaire</span></li></ul>","principes":"<p>La prise en charge est d'abord <span class=\"kw-ttt\">étiologique</span> (degré d'<span class=\"kw-alerte\">urgence</span> dicté par la cause) ; le traitement <span class=\"kw-ttt\">symptomatique de la diplopie</span> est commun à toutes <span class=\"kw-clinique\">les</span> étiologies.</p><p><strong>Traitement étiologique (priorité)</strong></p><ul><li><span class=\"kw-etio\">Anévrisme</span> : <span class=\"kw-ttt\">transfert neurochirurgical</span> immédiat ; <span class=\"kw-imagerie\">angioTDM/angioIRM</span>, puis <span class=\"kw-imagerie\">artériographie cérébrale</span> si négatif/douteux</li><li><span class=\"kw-etio\">Fistule carotido-caverneuse</span> : traitement <span class=\"kw-ttt\">endovasculaire (embolisation)</span> — bon <span class=\"kw-def\">pronostic</span> si traitée précocement</li><li><span class=\"kw-etio\">Méningoradiculite de Lyme</span> : <span class=\"kw-ttt\">ceftriaxone parentérale 2 g/j</span> pendant <span class=\"kw-chiffre\">15-21 jours</span> (jusqu'à<span class=\"kw-chiffre\"> 4 semaines</span>)</li><li><span class=\"kw-etio\">Zona ophtalmique</span> : <span class=\"kw-ttt\">valaciclovir/famciclovir per os 7 j</span> (immunocompétent) ou <span class=\"kw-ttt\">aciclovir IV 7-10 j</span> (immunodéprimé), débuté <span class=\"kw-chiffre\">&lt; 72 h</span></li><li><span class=\"kw-etio\">Syndrome de Tolosa-Hunt</span> : <span class=\"kw-ttt\">cortico-sensible</span></li><li><span class=\"kw-etio\">Atteinte microvasculaire</span> (<span class=\"kw-etio\">diabète</span>, HTA) : <span class=\"kw-ttt\">équilibrer les FRCV</span>, éliminer une <span class=\"kw-clinique\">maladie de Horton</span></li></ul><p><strong>Traitement symptomatique de la diplopie (indépendant de l'étiologie)</strong></p><p>À ne PAS proposer : <span class=\"kw-ci\">rééducation orthoptique</span> (favoriserait <span class=\"kw-clinique\">les</span> hyperactions compensatrices).</p><ul><li><strong>Phase précoce (1ers mois)</strong> : <span class=\"kw-ttt\">occlusion de l'œil paralysé</span> (Opticlude, Ocusert) pour le confort ; <span class=\"kw-ttt\">prismation</span> sur un verre quand possible ; <span class=\"kw-ttt\">toxine botulique</span> (VI post-traumatique, rang C)</li><li><strong>Phase tardive (rang C)</strong> : après <span class=\"kw-chiffre\">6 mois à 1 an</span> (délai de régénérescence nerveuse), <span class=\"kw-ttt\">traitement chirurgical</span> pour rétablir le parallélisme en position primaire</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Suivi</span> de la paralysie :</strong> <span class=\"kw-clinique\">test de Hess-Lancaster</span> répété (relevés successifs) pour objectiver l'<span class=\"kw-clinique\">évolution</span>.<br><strong>Délai de récupération :</strong> régénérescence nerveuse attendue en <span class=\"kw-chiffre\">6 mois à 1 an</span> avant d'envisager la <span class=\"kw-ttt\">chirurgie</span>.<br><strong>Cause microvasculaire :</strong> régression spontanée habituelle ; <span class=\"kw-ttt\">équilibrer tous les FRCV</span> et éliminer une <span class=\"kw-etio\">maladie de Horton</span>.<br><strong><span class=\"kw-clinique\">Zona</span> ophtalmique :</strong> surveiller la <span class=\"kw-etio\">kératite neurotrophique</span>, pouvant survenir <span class=\"kw-chiffre\">2-3 semaines après</span> la fin de l'<span class=\"kw-clinique\">éruption</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Diplopie aiguë récente — Vision double d'un objet unique","detail":"<h4>CAT — Diplopie aiguë — De l'occlusion d'un œil à l'orientation étiologique</h4>","branches":[{"to":"q-type","label":"Étape 1 : occlusion alternée d'un œil","color":"blue"}]},{"id":"q-type","kind":"decision","label":"Mono- ou binoculaire ? — Occlusion alternée d'un œil","branches":[{"to":"t-mono","label":"Monoculaire (persiste à l'occlusion de l'œil sain)","color":"green"},{"to":"q-triage","label":"Binoculaire (disparaît quel que soit l'œil occlus)","color":"amber"}]},{"id":"t-mono","kind":"terminal","label":"Cause ophtalmologique — consultation programmée — Diplopie monoculaire","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Persiste à l'occlusion de l'œil sain</span>, disparaît à l'occlusion de l'œil atteint</li><li>Pas de trouble du <span class=\"kw-def\">parallélisme oculaire</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Cornée</span> : ast<span class=\"kw-chiffre\">igm</span>atisme important, kératocône, taie cornéenne</li><li><span class=\"kw-etio\">Cristallin</span> : cataracte nucléaire, implant décentré</li><li><span class=\"kw-etio\">Iris</span> : iridodialyse traumatique ; <span class=\"kw-etio\">macula</span> (rare) : membrane épirétinienne</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Examen ophtalmologique</span> sans <span class=\"kw-alerte\">urgence</span></li><li>Cause fonctionnelle évoquée si bilan ophtalmologique normal</li></ul>"},{"id":"q-triage","kind":"decision","label":"Quel tableau d'orientation ? — Diplopie binoculaire = neurologique ou orbitaire","branches":[{"to":"t-anevrisme","label":"Paralysie du III + mydriase ± douleur","color":"red"},{"to":"t-grave","label":"Signes de gravité / trauma / immunodépression","color":"red"},{"to":"t-ait","label":"Diplopie transitoire &lt; 1 h","color":"amber"},{"to":"t-isolee","label":"Diplopie binoculaire isolée persistante","color":"amber"}]},{"id":"t-anevrisme","kind":"terminal","label":"Urgence vitale — transfert en neurochirurgie — Paralysie du III pupillaire ± douloureuse","color":"red","detail":"<h4>Clinique</h4><ul><li>Atteinte oculomotrice partielle MAIS avec <span class=\"kw-clinique\">signes pupillaires (mydriase)</span> d'atteinte intrinsèque</li><li><span class=\"kw-clinique\">Sujet jeune, absence de FRCV, céphalées</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Transfert en neurochirurgie</span> sans attendre l'imagerie</li><li><span class=\"kw-alerte\">Risque de HSA imminente</span> (paralysie annonciatrice d'une fissuration d'anévrisme)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">AngioTDM ou angioIRM</span> ; <span class=\"kw-imagerie\">artériographie cérébrale</span> si négatif/douteux et forte suspicion</li><li>Artère en cause : <span class=\"kw-etio\">communicante postérieure homolatérale</span> ou supraclinoïdienne</li></ul>"},{"id":"t-grave","kind":"terminal","label":"Imagerie cérébrale en urgence + avis spécialisé — Diplopie binoculaire avec signes de gravité","color":"red","detail":"<h4>Conduite</h4><ul><li>Contexte traumatique → <span class=\"kw-imagerie\">TDM cérébrale</span> en <span class=\"kw-alerte\">urgence</span>, 1re intention</li><li>Autres contextes → <span class=\"kw-imagerie\">IRM encéphalique</span> + avis neurologique</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">AVC du tronc cérébral</span> (diplopie + ataxie)</li><li><span class=\"kw-etio\">HTIC</span> : <span class=\"kw-clinique\">céphalées</span> + VI + nausées + <span class=\"kw-clinique\">œdème</span> papillaire</li><li><span class=\"kw-etio\">Hémorragie méningée / apoplexie pituitaire</span> : <span class=\"kw-clinique\">céphalées</span> violentes + <span class=\"kw-alerte\">syndrome méningé</span> non fébrile</li><li><span class=\"kw-etio\">Gayet-Wernicke</span> (alcoolique chronique), <span class=\"kw-etio\">Miller-Fisher</span> (ophtalmoplégie + ataxie + aréflexie)</li><li><span class=\"kw-etio\">Sinusite sphénoïdale fongique invasive</span> chez l'immunodéprimé (<span class=\"kw-def\">pronostic</span> très sombre)</li></ul>"},{"id":"t-ait","kind":"terminal","label":"<span class=\"kw-alerte\">AIT</span> vertébrobasilaire — bilan vasculaire urgent — Diplopie transitoire <span class=\"kw-chiffre\">< 1</span> h","color":"amber","detail":"<h4>Clinique</h4><ul><li>Survenue <span class=\"kw-clinique\">brutale</span>, durée <span class=\"kw-chiffre\">&lt; 1 h</span> ; examen souvent normal</li><li>± signes vertébrobasilaires : hémianopsie, ataxie, dysarthrie, <span class=\"kw-clinique\">vertige</span>, déficit hémicorporel</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM encéphalique</span> + exploration des TSAO et du polygone de Willis</li><li><span class=\"kw-imagerie\">ECG</span> + bilan de Horton (<span class=\"kw-bio\">VS, CRP</span>)</li></ul><h4>Conduite</h4><ul><li>Diagnostics différentiels : <span class=\"kw-etio\">myasthénie</span>, <span class=\"kw-alerte\">décompensation</span> d'un strabisme ancien</li></ul>"},{"id":"t-isolee","kind":"terminal","label":"Diplopie binoculaire isolée — bilan orienté par l'âge — Ni douleur, ni signe neuro, ni fluctuation évidente","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Myasthénie oculaire pure</span> : toujours évoquée — diplopie fluctuante, ptosis possible, indolore, sans mydriase</li><li><span class=\"kw-etio\">Ophtalmoplégie internucléaire</span> : <span class=\"kw-chiffre\">&lt; 40 ans</span> → SEP ; <span class=\"kw-chiffre\">&gt; 50 ans</span> (<span class=\"kw-etio\">FRCV</span>) → lacune du tronc</li><li><span class=\"kw-etio\">Atteinte microvasculaire</span> : cause la plus fréquente <span class=\"kw-chiffre\">&gt; 70 ans</span> et chez le diabétique</li><li><span class=\"kw-etio\">Tumeur</span> : possible à tout âge</li></ul><h4>Conduite</h4><ul><li>Rechercher/équilibrer <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">FRCV</span>, éliminer une <span class=\"kw-etio\">maladie de Horton</span></li><li>Si fluctuation : <span class=\"kw-bio\">Ac anti-récepteurs de l'acétylcholine</span> (absents dans <span class=\"kw-chiffre\">50 %</span> des formes oculaires), recherche de thymome</li></ul>"}]},"cards":[{"i":"00827b6576d5","n":102,"o":"102-10","u":"Diagnostic positif","t":"Devant une diplopie, connaître les arguments cliniques en faveur d’une myasthénie","q":"Quelles sont les trois caractéristiques cliniques presque pathognomoniques d'une diplopie myasthénique ?","a":"<p>Devant une <strong>diplopie binoculaire</strong>, les trois caractéristiques cliniques presque pathognomoniques d'une myasthénie sont :</p><ul><li>Une <strong>fluctuation</strong> de la diplopie, s'aggravant à l'effort et en fin de journée et disparaissant au repos et le matin au réveil.</li><li>Une diplopie <strong>non ou mal systématisée</strong>, c'est-à-dire qui ne cède pas à l'atteinte d'un nerf oculomoteur précis, changeante et souvent asymétrique.</li><li>Un <strong>ptosis associé</strong>, fluctuant lui aussi, bilatéral et souvent asymétrique.</li></ul>"},{"i":"2034770923be","n":102,"o":"102-10","u":"Diagnostic positif","t":"Devant une diplopie, connaître les arguments cliniques en faveur d’une myasthénie","q":"Quel est le signe clinique qui, s'il est positif, est pathognomonique de myasthénie en cas de ptosis associé à une diplopie ?","a":"<p>Le <strong>test du glaçon</strong> est pathognomonique : l'application de froid sur la paupière entraîne une amélioration transitoire du ptosis, voire sa disparition.</p>"},{"i":"eedb0d4fa5e2","n":102,"o":"102-10","u":"Diagnostic positif","t":"Devant une diplopie, connaître les arguments cliniques en faveur d’une myasthénie","q":"Quels sont les signes cliniques additionnels qui peuvent orienter vers une myasthénie en cas de diplopie ?","a":"<p>Outre les caractéristiques quasi pathognomoniques, d'autres signes cliniques peuvent orienter vers une myasthénie devant une diplopie :</p><ul><li>La diplopie est <strong>indolore</strong>.</li><li>Il n'y a <strong>pas de mydriase</strong> associée (les pupilles sont normales et réactives, car la myasthénie n'atteint pas le sphincter irien, dont les récepteurs sont muscariniques).</li><li>La présence de <strong>signes généraux associés</strong> comme un déficit proximal des membres fluctuant, des signes bulbaires (dysphonie, dysphagie, troubles de la mastication) ou une dyspnée d'effort.</li></ul>"},{"i":"10491dd4b3da","n":102,"o":"102-8","u":"Contenu multimédia","t":"Photographie/vidéo d’une paralysie extrinsèque/intrinsèque du III","q":"Quelles sont les composantes de la paralysie extrinsèque du nerf oculomoteur (III) ?","a":"<p>La paralysie extrinsèque du nerf oculomoteur (III) se manifeste par :</p><ul><li>Un <strong>ptosis complet</strong> de la paupière supérieure, due à la paralysie du muscle releveur de la paupière. Il peut masquer la diplopie (ptosis dit « providentiel »).</li><li>Un <strong>strabisme externe</strong>, l'œil étant dévié en abduction par hyperaction du muscle droit latéral (VI conservé).</li><li>L'œil est <strong>descendu et dévié en dehors</strong>, les muscles droit inférieur et oblique supérieur étant conservés (innervés par VI et IV).</li><li>Une <strong>paralysie de l'adduction, de l'élévation et de l'abaissement</strong> de l'œil.</li><li>À l'examen au verre rouge, on observe une <strong>diplopie horizontale croisée</strong> avec une composante verticale.</li></ul>"},{"i":"2a9a86205e30","n":102,"o":"102-8","u":"Contenu multimédia","t":"Photographie/vidéo d’une paralysie extrinsèque/intrinsèque du III","q":"Quelles sont les manifestations cliniques d'une paralysie intrinsèque du nerf oculomoteur (III) ?","a":"<p>La paralysie intrinsèque du nerf oculomoteur (III) se caractérise par :</p><ul><li>Une <strong>mydriase aréactive unilatérale</strong> ou une anisocorie, due à la paralysie du sphincter irien.</li><li>Une <strong>perte de l'accommodation</strong>, entraînant un flou visuel de près par paralysie du muscle ciliaire.</li><li>Un <strong>réflexe photomoteur direct aboli</strong> sur l'œil atteint, tandis que le réflexe consensuel est préservé sur l'œil controlatéral.</li></ul>"},{"i":"e55240044b5b","n":102,"o":"102-8","u":"Contenu multimédia","t":"Photographie/vidéo d’une paralysie extrinsèque/intrinsèque du III","q":"Quelle est la principale étiologie à considérer face à une paralysie purement extrinsèque du nerf oculomoteur (III) (pupille épargnée) chez un sujet de plus de 50 ans avec facteurs de risque cardiovasculaire ?","a":"<p>Face à une paralysie <strong>purement extrinsèque</strong> du nerf oculomoteur (III) (dite « pupil-sparing III », c'est-à-dire avec <strong>pupille préservée</strong>), chez un sujet de <strong>plus de 50 ans</strong> et présentant des <strong>facteurs de risque cardiovasculaire (FRCV)</strong>, l'étiologie à privilégier est une origine <strong>vasculaire ischémique</strong>, de type microangiopathie (ex: diabète, HTA) ou maladie de Horton.</p>"},{"i":"f7a160fe1608","n":102,"o":"102-8","u":"Contenu multimédia","t":"Photographie/vidéo d’une paralysie extrinsèque/intrinsèque du III","q":"Quelle est la valeur étiologique d'une paralysie du nerf oculomoteur (III) extrinsèque et intrinsèque douloureuse chez un sujet jeune, sans facteurs de risque cardiovasculaire ?","a":"<p>Une paralysie du nerf oculomoteur (III) associant une atteinte extrinsèque et intrinsèque, <strong>douloureuse</strong>, chez un sujet <strong>jeune et sans facteurs de risque cardiovasculaire (FRCV)</strong>, doit faire évoquer en urgence un <strong>anévrisme de l'artère communicante postérieure</strong> ou <strong>supraclinoïdien</strong>. Cela représente une situation d'hémorragie sous-arachnoïdienne (HSA) imminente et impose un <strong>transfert en neurochirurgie sans délai</strong>, avant même les résultats de l'imagerie.</p>"}]};